  function load(key, fallback) {
    try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; }
    catch (_) { return fallback; }
  }
  function save(key, val) { localStorage.setItem(key, JSON.stringify(val)); }

  /* =========================================================
     CAMADA REMOTA (Supabase) ÔÇö MODO H├ìBRIDO CENTRADO NA NUVEM
     - A NUVEM ('negociacoes') ├® a fonte definitiva.
     - LocalStorage ├® apenas espelho local/offline (fallback).
     - Toda a├º├úo de escrita vai para o Supabase IMEDIATAMENTE
       (upsert por linha) e o Realtime empurra para os demais
       dispositivos sem refresh.
     - Tabela 'negociacoes': { id text PK, data jsonb, updated_at timestamptz }
       'data' carrega a proposta INTEIRA, inclusive foto_produto
       (base64), descricao_tecnica e metadados de emiss├úo.
     ========================================================= */
  let _remoteOnExternal = null;     // callback p/ re-render das views
  const remote = {
    ready: () => !!window.supabaseClient,
    _syncing: false,   // flag para evitar pulls concorrentes
    channel: null,
    clientsChannel: null,
    status: () => window.supabaseClient ? 'connected' : 'offline',

    // Grava a negocia├º├úo na nuvem IMEDIATAMENTE (INSERT/UPDATE por linha).
    async upsert(prop) {
      if (!this.ready() || !prop || !prop.id) return;
      const row = {
        id: String(prop.id),
        data: prop,
        updated_at: prop.atualizadoEm || new Date().toISOString(),
        user_id: getCurrentUser().id,
      };
      const { error } = await window.supabaseClient
        .from('negociacoes').upsert(row, { onConflict: 'id' });
      if (error) console.warn('[Supabase] upsert falhou:', error.message, '->', prop.id);
    },

    // LEITURA OBRIGAT├ôRIA no carregamento: puxa a nuvem ANTES de popular o estado.
    // O estado local s├│ ├® preenchido AP├ôS a resposta do Supabase. Se a nuvem
    // falhar (offline), cai para o espelho local como fallback.
    async init(onChange) {
      _remoteOnExternal = onChange;
      if (!this.ready()) {
        console.info('[Supabase] offline ÔÇö tentando novamente em 3s...');
        setTimeout(() => { if (this.ready() && !this._syncing) this.init(onChange).catch(() => {}); }, 3000);
        return false;
      }
      if (this._syncing) { console.log('[Supabase] init ignorado ÔÇö j├í sincronizando'); return false; }
      this._syncing = true;

      // Cada opera├º├úo tem seu pr├│prio try/catch para que uma falha n├úo bloqueie as demais
      // 1 ÔÇö Pull negocia├º├Áes
      try {
        let negQuery = window.supabaseClient.from('negociacoes').select('*');
        if (!isAdmin()) negQuery = negQuery.eq('user_id', getCurrentUser().id);
        const { data: negData, error: negErr } = await negQuery.order('updated_at', { ascending: false });
        if (!negErr && negData) {
          const local = getPropostas();
          const cloudArr = negData.map(r => r.data).filter(Boolean);
          const localMap = {}; local.forEach(p => { if (p && p.id) localMap[p.id] = p; });
          const cloudMap = {}; cloudArr.forEach(p => { if (p && p.id) cloudMap[p.id] = p; });
          const allIds = new Set([...Object.keys(localMap), ...Object.keys(cloudMap)]);
          const merged = [];
          allIds.forEach(id => {
            const l = localMap[id]; const c = cloudMap[id];
            if (!c) { merged.push(l); return; }
            if (!l) { merged.push(c); return; }
            merged.push(new Date(l.atualizadoEm || 0).getTime() >= new Date(c.atualizadoEm || 0).getTime() ? l : c);
          });
          const latestLocal = getPropostas();
          const mergedIds = new Set(merged.map(p => p.id));
          latestLocal.forEach(p => { if (!mergedIds.has(p.id)) merged.push(p); });
          if (hasRealData()) persistReal(merged); else savePropostas(merged);
          // Push n├úo-bloqueante ÔÇö n├úo espera terminar para continuar
          this.pushAll().catch(e => console.warn('[Supabase] pushAll ignorado:', e));
        } else if (negErr) { console.warn('[Supabase] pull negociacoes falhou:', negErr.message); }
        console.log('[Supabase] negociacoes pull concluido. Local:', getPropostas().length, 'propostas');
      } catch (e) { console.warn('[Supabase] pull negociacoes erro:', e); }

      // 2 ÔÇö Pull clientes
      try {
        console.log('[Supabase] pull clientes: consultando tabela', CLIENTS_TABLE, '...');
        let cliQuery = window.supabaseClient.from(CLIENTS_TABLE).select('*');
        if (!isAdmin()) cliQuery = cliQuery.eq('user_id', getCurrentUser().id);
        const { data: cliData, error: cliErr } = await cliQuery;
        if (cliErr) {
          console.error('[Supabase] pull clientes ERRO:', cliErr.message, '| C├│digo:', cliErr.code, '| Detalhes:', cliErr.details);
          console.error('[Supabase] pull clientes ÔÇö verifique RLS: anon precisa de SELECT na tabela', CLIENTS_TABLE);
          if (typeof toast === 'function') toast('Erro ao buscar clientes da nuvem: ' + cliErr.message);
        }
        if (!cliErr && cliData) {
          console.log('[Supabase] clientes encontrados na nuvem:', cliData.length);
          const cloudMap = {};
          cliData.forEach(r => {
            if (!r || !r.id) return;
            let sh = Array.isArray(r.salesHistory) ? r.salesHistory : [];
            try { if (typeof r.salesHistory === 'string') sh = JSON.parse(r.salesHistory); } catch(_) { /* ignore parse errors */ }
            cloudMap[r.id] = {
              id: r.id, name: r.name || '', razaoSocial: r.razaoSocial || '',
              cnpj: r.cnpj || '', email: r.email || '', phone: r.phone || '',
              address: r.address || '', externalCode: r.externalCode || '',
              observations: r.observations || '', lastSale: r.lastSale || '',
              totalSpent: Number(r.totalSpent) || 0,
              salesHistory: sh, created_at: r.created_at,
            };
          });
          const localCli = getClients();
          console.log('[Supabase] clientes locais antes do merge:', localCli.length);
          localCli.forEach(c => { if (c && c.id && !cloudMap[c.id]) cloudMap[c.id] = c; });
          saveClients(Object.values(cloudMap));
          console.log('[Supabase] clientes sincronizados (ap├│s merge) ÔÇö total:', Object.values(cloudMap).length);
        }
        // Push clientes locais que n├úo est├úo na nuvem
        this.pushAllClients().catch(e => console.error('[Supabase] pushAllClients exce├º├úo:', e));
      } catch (e) { console.error('[Supabase] pull clientes erro geral:', e); }

      // 3 ÔÇö Pull nfe_imports
      try { await this.pullNfeImports(); } catch (e) { console.warn('[Supabase] pullNfeImports erro:', e); }
      // Push retroativo: envia NFs locais que ainda n├úo est├úo na nuvem
      try { await this.pushExistingNfeImports(); } catch (e) { console.warn('[Supabase] pushExistingNfeImports erro:', e); }

      // 3b ÔÇö Pull produtos (se houver na nuvem, sobrep├Áe local)
      try { await this.pullProducts(); } catch (e) { console.warn('[Supabase] pullProducts erro:', e); }
      // Push produtos locais para a nuvem
      try { await this.pushAllProducts(); } catch (e) { console.warn('[Supabase] pushAllProducts erro:', e); }

      // 3c ÔÇö Consolida itens das NF-e importadas no price history
      try { this.syncProductsFromNfeImports(); } catch (e) { console.warn('[Supabase] syncProductsFromNfeImports erro:', e); }

      // 4 ÔÇö Assinaturas Realtime
      try { this.subscribe(); } catch (e) { console.warn('[Supabase] subscribe erro:', e); }
      try { this.subscribeClients(); } catch (e) { console.warn('[Supabase] subscribeClients erro:', e); }
      try { this.subscribeNfeImports(); } catch (e) { console.warn('[Supabase] subscribeNfeImports erro:', e); }

      // 5 ÔÇö Log final com totais
      console.log('[Supabase] init concluido. Clientes:', getClients().length, 'NFe imports:', load(KEY_NFE_IMPORTS, []).length, 'Propostas:', getPropostas().length);

      // 6 ÔÇö SEMPRE dispara refresh da UI, mesmo se algum pull falhou
      if (typeof _remoteOnExternal === 'function') _remoteOnExternal();
      this._syncing = false;
      return true;
    },

    // Espelha TODAS as negocia├º├Áes locais na nuvem (usado no bootstrap).
    async pushAll() {
      if (!this.ready()) return;
      const arr = getPropostas();
      if (!arr.length) { console.log('[Supabase] pushAll: nenhuma proposta'); return; }
      const uid = getCurrentUser().id;
      const rows = arr.map(p => ({
        id: String(p.id),
        data: p,
        updated_at: p.atualizadoEm || new Date().toISOString(),
        user_id: uid,
      }));
      const { error } = await window.supabaseClient
        .from('negociacoes').upsert(rows, { onConflict: 'id' });
      if (error) {
        console.warn('[Supabase] pushAll falhou:', error.message);
        if (typeof toast === 'function') toast('Erro ao enviar propostas: ' + error.message);
      } else {
        console.log('[Supabase] pushAll OK:', rows.length, 'propostas');
      }
    },

    // Puxa dados da nuvem sem recriar subscriptions (├║til para refresh manual)
    async pullData() {
      if (!this.ready()) return;
      // Negocia├º├Áes
      try {
        let negQuery = window.supabaseClient.from('negociacoes').select('*');
        if (!isAdmin()) negQuery = negQuery.eq('user_id', getCurrentUser().id);
        const { data: negData, error: negErr } = await negQuery.order('updated_at', { ascending: false });
        if (!negErr && negData) {
          const local = getPropostas();
          const cloudArr = negData.map(r => r.data).filter(Boolean);
          const localMap = {}; local.forEach(p => { if (p && p.id) localMap[p.id] = p; });
          const cloudMap = {}; cloudArr.forEach(p => { if (p && p.id) cloudMap[p.id] = p; });
          const allIds = new Set([...Object.keys(localMap), ...Object.keys(cloudMap)]);
          const merged = [];
          allIds.forEach(id => {
            const l = localMap[id]; const c = cloudMap[id];
            if (!c) { merged.push(l); return; }
            if (!l) { merged.push(c); return; }
            merged.push(new Date(l.atualizadoEm || 0).getTime() >= new Date(c.atualizadoEm || 0).getTime() ? l : c);
          });
          const latestLocal = getPropostas();
          const mergedIds = new Set(merged.map(p => p.id));
          latestLocal.forEach(p => { if (!mergedIds.has(p.id)) merged.push(p); });
          if (hasRealData()) persistReal(merged); else savePropostas(merged);
        }
      } catch (e) { console.warn('[Supabase] pull negociacoes falhou:', e); }
      // Clientes
      try {
        let cliQuery = window.supabaseClient.from(CLIENTS_TABLE).select('*');
        if (!isAdmin()) cliQuery = cliQuery.eq('user_id', getCurrentUser().id);
        const { data: cliData, error: cliErr } = await cliQuery;
        if (cliErr) {
          console.error('[Supabase] pullData clientes ERRO:', cliErr.message, '| C├│digo:', cliErr.code, '| Detalhes:', cliErr.details);
        }
        if (!cliErr && cliData) {
          console.log('[Supabase] pullData clientes:', cliData.length, 'registros da nuvem');
          const cloudMap = {};
          cliData.forEach(r => {
            if (!r || !r.id) return;
            let sh = Array.isArray(r.salesHistory) ? r.salesHistory : [];
            try { if (typeof r.salesHistory === 'string') sh = JSON.parse(r.salesHistory); } catch(_) { /* ignore parse errors */ }
            cloudMap[r.id] = {
              id: r.id, name: r.name || '', razaoSocial: r.razaoSocial || '',
              cnpj: r.cnpj || '', email: r.email || '', phone: r.phone || '',
              address: r.address || '', externalCode: r.externalCode || '',
              observations: r.observations || '', lastSale: r.lastSale || '',
              totalSpent: Number(r.totalSpent) || 0,
              salesHistory: sh, created_at: r.created_at,
            };
          });
          const localCli = getClients();
          localCli.forEach(c => { if (c && c.id && !cloudMap[c.id]) cloudMap[c.id] = c; });
          saveClients(Object.values(cloudMap));
        }
      } catch (e) { console.error('[Supabase] pull clientes erro geral:', e); }
    },

    // Sobe TODOS os clientes para a nuvem
    async pushAllClients() {
      if (!this.ready()) { console.error('[Supabase] pushAllClients: supabaseClient n├úo est├í pronto'); return; }
      const arr = getClients();
      if (!arr.length) { console.log('[Supabase] pushAllClients: nenhum cliente local para enviar'); return; }
      console.log('[Supabase] pushAllClients: enviando', arr.length, 'clientes...');
      const uid = getCurrentUser().id;
      const rows = arr.map(c => ({
        id: String(c.id), name: c.name || '', razaoSocial: c.razaoSocial || '',
        cnpj: c.cnpj || '', email: c.email || '', phone: c.phone || '',
        address: c.address || '',
        observations: c.observations || '', lastSale: c.lastSale || '',
        totalSpent: c.totalSpent || 0,
        salesHistory: Array.isArray(c.salesHistory) ? c.salesHistory : [],
        user_id: uid,
      }));
      const { data, error } = await window.supabaseClient
        .from(CLIENTS_TABLE).upsert(rows, { onConflict: 'id' }).select();
      if (error) {
        console.error('[Supabase] pushAllClients ERRO:', error.message, '| C├│digo:', error.code, '| Detalhes:', error.details);
        console.error('[Supabase] pushAllClients ÔÇö verifique RLS da tabela', CLIENTS_TABLE, ': anon precisa de INSERT/UPDATE');
        if (typeof toast === 'function') toast('Erro ao enviar clientes: ' + error.message);
      } else {
        console.log('[Supabase] pushAllClients OK:', (data || rows).length, 'clientes na nuvem');
      }
    },

    // Remove uma negocia├º├úo da nuvem (DELETE imediato).
    async remove(id) {
      if (!this.ready() || !id) return;
      let delQuery = window.supabaseClient.from('negociacoes').delete().eq('id', id);
      if (!isAdmin()) delQuery = delQuery.eq('user_id', getCurrentUser().id);
      const { error } = await delQuery;
      if (error) console.warn('[Supabase] remove falhou:', error.message);
    },

    // Assina o Realtime da tabela 'negociacoes' (INSERT/UPDATE/DELETE).
    subscribe() {
      if (!this.ready()) return;
      this.channel = window.supabaseClient
        .channel('negociacoes-rt')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'negociacoes' },
          (payload) => this.applyExternal(payload))
        .subscribe((status) => {
          if (status === 'CHANNEL_ERROR') console.warn('[Supabase] realtime CHANNEL_ERROR ÔÇö fallback via REST');
          else console.info('[Supabase] realtime:', status);
        });
    },

    // Aplica uma mudan├ºa vinda de OUTRO dispositivo e re-renderiza na hora.
    applyExternal(payload) {
      if (payload.eventType === 'DELETE') {
        const id = payload.old && payload.old.id;
        if (!id) return;
        const arr = getPropostas().filter(x => String(x.id) !== String(id));
        if (hasRealData()) persistReal(arr); else savePropostas(arr);
      } else {
        const prop = payload.new && payload.new.data;
        if (!prop || !prop.id) return;
        const arr = getPropostas();
        const i = arr.findIndex(x => String(x.id) === String(prop.id));
        if (i >= 0) arr[i] = prop; else arr.push(prop);
        if (hasRealData()) persistReal(arr); else savePropostas(arr);
      }
      if (typeof _remoteOnExternal === 'function') _remoteOnExternal();
    },

    // ÔöÇÔöÇÔöÇ Realtime: Clientes ÔöÇÔöÇÔöÇ
    subscribeClients() {
      if (!this.ready()) return;
      this.clientsChannel = window.supabaseClient
        .channel('clients-rt')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'clients' },
          (payload) => this.applyExternalClients(payload))
        .subscribe((status) => {
          if (status === 'CHANNEL_ERROR') console.warn('[Supabase] clients realtime CHANNEL_ERROR');
          else console.info('[Supabase] clients realtime:', status);
        });
    },

    applyExternalClients(payload) {
      const arr = getClients();
      if (payload.eventType === 'DELETE') {
        const id = payload.old && payload.old.id;
        if (!id) return;
        saveClients(arr.filter(x => String(x.id) !== String(id)));
      } else {
        const row = payload.new;
        if (!row || !row.id) return;
        const client = {
          id: row.id,
          name: row.name || '',
          razaoSocial: row.razaoSocial || '',
          cnpj: row.cnpj || '',
          email: row.email || '',
          phone: row.phone || '',
          address: row.address || '',
          externalCode: row.externalCode || '',
          observations: row.observations || '',
          lastSale: row.lastSale || '',
          totalSpent: Number(row.totalSpent) || 0,
          salesHistory: Array.isArray(row.salesHistory) ? row.salesHistory : [],
          created_at: row.created_at,
        };
        const i = arr.findIndex(x => String(x.id) === String(client.id));
        if (i >= 0) arr[i] = client; else arr.push(client);
        saveClients(arr);
      }
      if (typeof _remoteOnExternal === 'function') _remoteOnExternal();
    },

    // ÔöÇÔöÇÔöÇ NF-e imports ÔöÇÔöÇÔöÇ
    async pushNfeImports(rows) {
      if (!this.ready()) { console.error('[Supabase] pushNfeImports: supabaseClient n├úo est├í pronto'); return; }
      if (!rows.length) { console.log('[Supabase] pushNfeImports: 0 registros para enviar'); return; }
      // Garante que importedAt e items estejam presentes
      const uid = getCurrentUser().id;
      const enriched = rows.map(r => ({
        ...r,
        user_id: uid,
        importedAt: r.importedAt || new Date().toISOString(),
        items: Array.isArray(r.items) ? r.items : [],
      }));
      console.log('[Supabase] pushNfeImports: enviando', enriched.length, 'registros...');
      const { data, error } = await window.supabaseClient
        .from(NFE_IMPORTS_TABLE).upsert(enriched, { onConflict: 'nfId' }).select();
      if (error) {
        console.error('[Supabase] pushNfeImports ERRO:', error.message, '| C├│digo:', error.code, '| Detalhes:', error.details);
        console.error('[Supabase] pushNfeImports ÔÇö verifique RLS da tabela', NFE_IMPORTS_TABLE, ': anon precisa de INSERT/UPDATE e colunas: nfId, nfNumber, serie, date, supplierName, supplierCnpj, clientName, clientCnpj, productCount, importedAt');
        if (typeof toast === 'function') toast('Erro ao enviar NF-e: ' + error.message);
      } else {
        console.log('[Supabase] pushNfeImports OK:', (data || enriched).length, 'registros na nuvem');
      }
    },

    async pullNfeImports() {
      if (!this.ready()) { console.error('[Supabase] pullNfeImports: supabaseClient n├úo est├í pronto'); return; }
      if (this._syncing) { console.log('[Supabase] pullNfeImports ignorado ÔÇö j├í sincronizando'); return; }
      this._syncing = true;
      try {
        console.log('[Supabase] pullNfeImports: consultando tabela', NFE_IMPORTS_TABLE, '...');
        let q = window.supabaseClient.from(NFE_IMPORTS_TABLE).select('*');
        if (!isAdmin()) q = q.eq('user_id', getCurrentUser().id);
        const { data, error } = await q.order('importedAt', { ascending: false });
        if (error) {
          console.error('[Supabase] pullNfeImports ERRO:', error.message, '| C├│digo:', error.code, '| Detalhes:', error.details);
          console.error('[Supabase] pullNfeImports ÔÇö verifique RLS: anon precisa de SELECT em', NFE_IMPORTS_TABLE);
          if (typeof toast === 'function') toast('Erro ao buscar NF-e da nuvem: ' + error.message);
        }
        if (!error && data) {
          save(KEY_NFE_IMPORTS, data);
          console.log('[Supabase] pullNfeImports OK:', data.length, 'registros');
        }
      } catch (e) { console.error('[Supabase] pullNfeImports erro geral:', e); }
      this._syncing = false;
    },

    // Push retroativo em lote: envia TODAS as NFs do localStorage para a nuvem
    async pushExistingNfeImports() {
      console.log('[Supabase] pushExistingNfeImports: lendo localStorage...');
      const local = load(KEY_NFE_IMPORTS, []);
      if (!local.length) { console.log('[Supabase] pushExistingNfeImports: nenhuma NF local'); return 0; }
      const rows = local.map(n => ({
        nfId: n.nfId,
        nfNumber: n.nfNumber || '',
        serie: n.serie || '',
        date: n.date || '',
        supplierName: n.supplierName || '',
        supplierCnpj: n.supplierCnpj || '',
        clientName: n.clientName || '',
        clientCnpj: n.clientCnpj || '',
        productCount: n.productCount || 0,
        importedAt: n.importedAt || new Date().toISOString(),
        items: Array.isArray(n.items) ? n.items : [],
      }));
      await this.pushNfeImports(rows);
      console.log('[Supabase] pushExistingNfeImports concluido:', rows.length, 'NFs enviadas');
      return rows.length;
    },

    subscribeNfeImports() {
      if (!this.ready()) return;
      this.nfeChannel = window.supabaseClient
        .channel('nfe-imports-rt')
        .on('postgres_changes', { event: '*', schema: 'public', table: NFE_IMPORTS_TABLE },
          (payload) => this.applyExternalNfeImport(payload))
        .subscribe((status) => {
          if (status === 'CHANNEL_ERROR') console.warn('[Supabase] nfe_imports realtime CHANNEL_ERROR');
          else console.info('[Supabase] nfe_imports realtime:', status);
        });
    },

    applyExternalNfeImport(payload) {
      const arr = load(KEY_NFE_IMPORTS, []);
      if (payload.eventType === 'DELETE') {
        const id = payload.old && payload.old.nfId;
        if (!id) return;
        save(KEY_NFE_IMPORTS, arr.filter(x => x.nfId !== id));
      } else {
        const row = payload.new;
        if (!row || !row.nfId) return;
        const i = arr.findIndex(x => x.nfId === row.nfId);
        if (i >= 0) arr[i] = row; else arr.push(row);
        save(KEY_NFE_IMPORTS, arr);
      }
      if (typeof _remoteOnExternal === 'function') _remoteOnExternal();
    },

    // ÔöÇÔöÇÔöÇ Products sync ÔöÇÔöÇÔöÇ
    // NOTA: A tabela 'products' no Supabase usa id UUID.
    // Produtos locais t├¬m ids como "P001" ÔÇö enviados apenas como 'code'.
    // O merge usa 'code' como chave de correspond├¬ncia.
    async pushAllProducts() {
      if (!this.ready()) { console.error('[Supabase] pushAllProducts: supabaseClient n├úo est├í pronto'); return; }
      const arr = getProdutos();
      if (!arr.length) { console.log('[Supabase] pushAllProducts: nenhum produto local'); return; }
      console.log('[Supabase] pushAllProducts: enviando', arr.length, 'produtos...');
      const uid = getCurrentUser().id;
      const rows = arr.map(p => {
        const rawId = String(p.id);
        const isUuid = rawId.includes('-');
        const row = {
          code: rawId,
          name: p.nome || '',
          ncm: p.ncm || '',
          last_price: Number(p.preco) || 0,
          total_bought: 0,
          supplier_name: p.fornecedor || '',
          nf_number: '',
          user_id: uid,
        };
        if (isUuid) row.id = rawId;
        return row;
      });
      const { data, error } = await window.supabaseClient
        .from(PRODS_TABLE).upsert(rows, { onConflict: 'code' }).select();
      if (error) {
        console.error('[Supabase] pushAllProducts ERRO:', error.message, '| C├│digo:', error.code, '| Detalhes:', error.details);
        console.error('[Supabase] pushAllProducts ÔÇö verifique RLS da tabela', PRODS_TABLE, ': anon precisa de INSERT/UPDATE');
        if (typeof toast === 'function') toast('Erro ao enviar produtos: ' + error.message);
      } else {
        console.log('[Supabase] pushAllProducts OK:', (data || rows).length, 'produtos na nuvem');
      }
    },

    async pullProducts() {
      if (!this.ready()) { console.error('[Supabase] pullProducts: supabaseClient n├úo est├í pronto'); return; }
      if (this._syncing) { console.log('[Supabase] pullProducts ignorado ÔÇö j├í sincronizando'); return; }
      this._syncing = true;
      try {
        console.log('[Supabase] pullProducts: consultando tabela', PRODS_TABLE, '...');
        let q = window.supabaseClient.from(PRODS_TABLE).select('*');
        if (!isAdmin()) q = q.eq('user_id', getCurrentUser().id);
        const { data, error } = await q.order('code', { ascending: true });
        if (error) {
          console.error('[Supabase] pullProducts ERRO:', error.message, '| C├│digo:', error.code, '| Detalhes:', error.details);
          console.error('[Supabase] pullProducts ÔÇö verifique RLS: anon precisa de SELECT em', PRODS_TABLE);
          if (typeof toast === 'function') toast('Erro ao buscar produtos da nuvem: ' + error.message);
        }
        if (!error && data) {
          const mapped = data.map(r => ({
            id: r.code || r.id, nome: r.name || '',
            ncm: r.ncm || '', preco: Number(r.last_price) || 0,
            fornecedor: r.supplier_name || '',
          }));
          if (mapped.length) {
            const local = getProdutos();
            // Merge: preserva campos locais que n├úo existem na nuvem (categoria, descricao, etc.)
            const merged = mapped.map(m => {
              const localMatch = local.find(x => x.id === m.id);
              return localMatch ? { ...m, ...localMatch, ...m } : m;
            });
            save(KEY_PROD, merged);
            console.log('[Supabase] pullProducts OK:', merged.length, 'produtos');
          }
        }
      } catch (e) { console.error('[Supabase] pullProducts erro geral:', e); }
      this._syncing = false;
    },

    // Extrai e consolida itens de todas as NF-e importadas em uma lista de rastreio de produtos.
    // Agrupa por c├│digo do produto, calcula ├║ltimo pre├ºo, total comprado e fornecedores.
    syncProductsFromNfeImports() {
      console.log('[Supabase] syncProductsFromNfeImports: consolidando...');
      const imports = getNfeImports();
      if (!imports.length) { console.log('[Supabase] syncProductsFromNfeImports: nenhum import NF-e'); return []; }

      const map = {};
      imports.forEach(nf => {
        const items = nf.items || [];
        items.forEach(it => {
          if (!it.codigo && !it.nome) return;
          const key = it.codigo || it.nome;
          if (!map[key]) {
            map[key] = {
              code: it.codigo || '',
              name: it.nome || 'ÔÇö',
              ncm: it.ncm || '',
              entries: [],
            };
          }
          map[key].entries.push({
            unitPrice: it.unitPrice || 0,
            quantity: it.quantidade || 0,
            date: nf.date || '',
            nfNumber: nf.nfNumber || '',
            supplierName: nf.supplierName || '',
            supplierCnpj: nf.supplierCnpj || '',
          });
        });
      });

      // Se h├í itens das NF-e, salva como price history para a UI consumir
      const result = Object.values(map);
      if (result.length) {
        // Converte para o formato priceHist para compatibilidade com renderProdutos
        const priceHist = [];
        result.forEach(g => {
          g.entries.forEach(e => {
            priceHist.push({
              id: 'NFeItem-' + g.code + '-' + e.nfNumber,
              productCode: g.code,
              productName: g.name,
              ncm: g.ncm,
              nfNumber: e.nfNumber,
              date: e.date,
              supplierName: e.supplierName,
              supplierCnpj: e.supplierCnpj,
              quantity: e.quantity,
              unitPrice: e.unitPrice,
              total: e.unitPrice * e.quantity,
              clientCnpj: '',
            });
          });
        });
        // Mescla com price history existente (de clientes)
        const existing = load(KEY_PRICE_HISTORY, []);
        const merged = [...existing];
        const existKeys = new Set(existing.map(e => e.id));
        let added = 0;
        priceHist.forEach(e => {
          if (!existKeys.has(e.id)) { merged.push(e); added++; }
        });
        if (added) {
          save(KEY_PRICE_HISTORY, merged);
          console.log('[Supabase] syncProductsFromNfeImports: adicionados', added, 'itens ao price history');
        } else {
          console.log('[Supabase] syncProductsFromNfeImports: sem novidades');
        }
      }
      return result;
    },

    // Push completo de todos os dados locais para a nuvem
    async pushAllData() {
      const results = await Promise.allSettled([
        this.pushAll(),
        this.pushAllClients(),
        this.pushExistingNfeImports(),
        this.pushAllProducts(),
      ]);
      const ok = results.filter(r => r.status === 'fulfilled').length;
      console.log('[Supabase] pushAllData concluido:', ok, 'de', results.length, 'etapas OK');
      if (typeof toast === 'function') toast('Sincroniza├º├úo conclu├¡da! Dados dispon├¡veis na nuvem.');
    },
  };

  // Escrita imediata na nuvem para a negocia├º├úo alterada (espelho local em 2┬¬ via).
  function markDirty(prop) {
    if (!remote.ready()) return;
    if (prop) remote.upsert(prop); else remote.pushAll();
  }

  // Semeia APENAS o cat├ílogo de produtos (usado pelo gerador de propostas).
  // Propostas fict├¡cias N├âO s├úo mais semeadas ÔÇö o sistema usa exclusivamente
  // as propostas reais da chave 'duocrm-quotes'.
  function ensureSeed(force) {
    if (force || !localStorage.getItem(KEY_PROD)) save(KEY_PROD, SEED_PRODUTOS);
    if (force || !localStorage.getItem(KEY_SEQ)) save(KEY_SEQ, 1100);
  }

  // Restaura propostas de demonstra├º├úo sob demanda (opcional, bot├úo "Dados demo").
  function seedDemoPropostas() { save(KEY_PROP, seedPropostas()); }

  // ---- Produtos ----
  const getProdutos = () => load(KEY_PROD, []);
  const saveProdutos = (arr) => save(KEY_PROD, arr);
  function upsertProduto(p) {
    const arr = getProdutos();
    if (p.id) {
      const i = arr.findIndex(x => x.id === p.id);
      if (i >= 0) arr[i] = { ...arr[i], ...p }; else arr.push(p);
    } else {
      p.id = 'P' + String(Date.now()).slice(-6);
      arr.push(p);
    }
    saveProdutos(arr);
    return p;
  }
  function deleteProduto(id) { saveProdutos(getProdutos().filter(x => x.id !== id)); }

  // ---- Adaptador de dados REAIS (chave 'duocrm-quotes' do app antigo) ----
  // Schema real do app antigo (Energiza/DuoCRM):
  //   id, clientName, projectName, value, margin, description,
  //   contactPhone, contactEmail, estimatedDate, createdAt, status,
  //   priority, supplierLinks, productPhoto(s), lossReason...
  // Funil antigo: new | analysis | sent | negotiation | won | lost
  const STATUS_MAP = {
    new: 'aberto', analysis: 'aberto', rascunho: 'aberto', draft: 'aberto', aberto: 'aberto', triagem: 'aberto', elaboracao: 'aberto',
    sent: 'enviada', enviada: 'enviada', enviado: 'enviada',
    precificacao: 'precificacao', quoting: 'precificacao', montagem: 'precificacao',
    negotiation: 'negociacao', negociacao: 'negociacao', pending: 'negociacao', ajustes: 'negociacao',
    won: 'ganho', ganho: 'ganho', ganha: 'ganho', fulfilled: 'ganho', faturado: 'ganho', aprovado: 'ganho', sucesso: 'ganho',
    lost: 'perdido', rejected: 'perdido', perdido: 'perdido', perdida: 'perdido', cancelada: 'perdido',
  };

  function pick(o, keys, def) { for (const k of keys) { if (o && o[k] != null && o[k] !== '') return o[k]; } return def; }

  // Converte um "quote" do formato antigo para o formato interno deste CRM.
  function mapQuote(q, i) {
    const rawStatus = String(pick(q, ['status', 'stage', 'column'], 'new')).toLowerCase().trim();
    const status = STATUS_MAP[rawStatus] || 'aberto';

    const criadoEm = pick(q, ['createdAt', 'criadoEm', 'date', 'data'], new Date().toISOString());
    const atualizadoEm = pick(q, ['updatedAt', 'atualizadoEm', 'lastUpdate', 'movedAt', 'estimatedDate'], criadoEm);

    const projeto = pick(q, ['projectName', 'projeto', 'project'], '');
    const descricao = pick(q, ['description', 'descricao', 'desc'], '');
    // Categoria: usa projectName como r├│tulo do equipamento/servi├ºo.
    const categoria = pick(q, ['category', 'categoria'], projeto || 'Geral');

    // Foto do produto (se houver).
    const foto = pick(q, ['productPhoto'], '') || (Array.isArray(q && q.productPhotos) ? (q.productPhotos[0] || '') : '');

    // Itens: o app antigo N├âO usa itens detalhados ÔÇö o valor est├í em `value`.
    // Se existir um array de itens (vers├Áes futuras), usa-o; sen├úo cria item sint├®tico a partir de `value`.
    const rawItens = pick(q, ['items', 'lineItems', 'products', 'itens'], null);
    let itens;
    if (Array.isArray(rawItens) && rawItens.length) {
      itens = rawItens.map(it => ({
        produtoId: pick(it, ['productId', 'produtoId', 'id'], ''),
        nome: pick(it, ['name', 'productName', 'itemName', 'nome'], projeto || 'Item'),
        descricao: pick(it, ['description', 'descricao', 'desc'], ''),
        categoria: pick(it, ['category', 'categoria'], categoria),
        preco: Number(pick(it, ['price', 'unitPrice', 'preco', 'valorUnitario'], 0)) || 0,
        qtd: Number(pick(it, ['quantity', 'qty', 'qtd', 'quantidade'], 1)) || 1,
        foto: pick(it, ['image', 'imageUrl', 'foto', 'img'], foto),
      }));
    } else {
      const valor = Number(pick(q, ['value', 'total', 'totalValue', 'totalPrice', 'amount', 'valorTotal', 'valor'], 0)) || 0;
      itens = [{
        produtoId: '',
        nome: projeto || pick(q, ['title', 'titulo'], 'Proposta'),
        descricao,
        categoria,
        preco: valor,
        qtd: 1,
        foto,
      }];
    }

    // Campos de n├¡vel da proposta (usados pelo PDF t├®cnico / card do funil).
    const itemPrincipal = (Array.isArray(itens) && itens[0]) || {};
    const foto_produto = pick(q, ['foto_produto', 'productPhoto'], '') || itemPrincipal.foto || (Array.isArray(q && q.productPhotos) ? (q.productPhotos[0] || '') : '');
    const descricao_tecnica = pick(q, ['descricao_tecnica', 'description', 'descricao', 'desc'], '') || itemPrincipal.descricao || '';

    return {
      id: String(pick(q, ['id', 'quoteNumber', 'proposalId', 'numero'], 'PROP-R' + (i + 1))),
      cliente: pick(q, ['clientName', 'customerName', 'clientHospital', 'hospital', 'companyName', 'cliente'], 'Cliente'),
      contato: pick(q, ['contactName', 'clientContact', 'contact', 'contato', 'responsavel', 'contactEmail', 'contactPhone'], ''),
      projeto,
      status,
      categoria,
      itens,
      foto_produto,
      descricao_tecnica,
      criadoEm: new Date(criadoEm).toISOString(),
      atualizadoEm: new Date(atualizadoEm).toISOString(),
      last_interaction_date: new Date(atualizadoEm).toISOString(),
      data_movimentacao: new Date(atualizadoEm).toISOString(),
      validade: pick(q, ['validity', 'validade'], '15 dias'),
      prazo: pick(q, ['deliveryTerm', 'prazo'], '30 dias ├║teis'),
      pagamento: pick(q, ['paymentTerms', 'payment', 'pagamento'], 'A combinar'),
      motivo_perda: pick(q, ['motivo_perda', 'lossReason', 'lossDetails'], ''),
      _origem: 'real',
    };
  }

  // L├¬ e mapeia as propostas reais salvas na chave do app antigo.
  function readRealQuotes() {
    const raw = load(KEY_REAL, null);
    if (!raw) return [];
    const arr = Array.isArray(raw) ? raw : (Array.isArray(raw.quotes) ? raw.quotes : []);
    try { return arr.map(mapQuote).map(normalizeMidia); } catch (e) { console.error('Falha ao mapear duocrm-quotes:', e); return []; }
  }

  // Importa um backup manual (texto colado com o JSON bruto do 'duocrm-quotes').
  // Faz JSON.parse, normaliza para array e salva EXATAMENTE na chave lida pelo CRM.
  function importBackup(text) {
    let data;
    try { data = JSON.parse(String(text).trim()); }
    catch (_) { throw new Error('Backup inv├ílido: o texto colado n├úo ├® um JSON v├ílido.'); }

    let arr;
    if (Array.isArray(data)) arr = data;
    else if (data && Array.isArray(data.quotes)) arr = data.quotes;               // { quotes: [...] }
    else if (data && Array.isArray(data['duocrm-quotes'])) arr = data['duocrm-quotes'];
    else if (data && typeof data === 'object') arr = [data];                       // objeto ├║nico = 1 proposta
    else throw new Error('Backup inv├ílido: esperado um array de propostas ou objeto com "quotes".');

    if (!arr.length) throw new Error('Backup vazio: nenhuma proposta encontrada no texto colado.');

    // Limpa qualquer res├¡duo de dados demo e injeta o backup na chave real.
    localStorage.removeItem(KEY_PROP);
    save(KEY_REAL, arr);
    return arr.length;
  }

  function exportBackup() {
    const raw = load(KEY_REAL, []);
    const arr = Array.isArray(raw) ? raw : (Array.isArray(raw.quotes) ? raw.quotes : []);
    return JSON.stringify(arr, null, 2);
  }

  const hasRealData = () => readRealQuotes().length > 0;

  // Parseia CSV para array de propostas.
  // Formato esperado: header com colunas id,cliente,contato,categoria,status,validade,prazo,pagamento,item_nome,item_qtd,item_preco,item_foto
  // Linhas com mesmo id s├úo agrupadas em uma ├║nica proposta com m├║ltiplos itens.
  function importCsv(text) {
    const lines = text.trim().split(/\r?\n/);
    if (lines.length < 2) throw new Error('CSV deve ter cabe├ºalho + pelo menos 1 linha.');
    const heads = lines[0].split(',').map(h => h.trim().toLowerCase());
    const byId = {};
    for (let i = 1; i < lines.length; i++) {
      const vals = parseCsvLine(lines[i]);
      if (vals.length < heads.length) continue;
      const row = {};
      heads.forEach((h, j) => row[h] = (vals[j] || '').trim());
      if (!row.id) continue;
      if (!byId[row.id]) {
        byId[row.id] = {
          id: row.id,
          cliente: row.cliente || '',
          contato: row.contato || '',
          categoria: row.categoria || '',
          status: row.status || 'aberto',
          validade: row.validade || '',
          prazo: row.prazo || '',
          pagamento: row.pagamento || '',
          criadoEm: row.criado_em || new Date().toISOString(),
          atualizadoEm: row.atualizado_em || new Date().toISOString(),
          data_movimentacao: row.data_movimentacao || new Date().toISOString(),
          itens: [],
        };
      }
      byId[row.id].itens.push({
        produtoId: row.item_id || ('IMP-' + row.id + '-' + byId[row.id].itens.length),
        nome: row.item_nome || '',
        descricao: row.item_descricao || '',
        categoria: row.item_categoria || row.categoria || '',
        preco: parseFloat(row.item_preco) || 0,
        qtd: parseInt(row.item_qtd) || 1,
        foto: row.item_foto || '',
      });
    }
    const arr = Object.values(byId);
    if (!arr.length) throw new Error('Nenhuma proposta encontrada no CSV.');
    localStorage.removeItem(KEY_PROP);
    save(KEY_REAL, arr);
    return arr.length;
  }

  // Parseia uma linha CSV respeitando aspas duplas.
  function parseCsvLine(line) {
    const result = [];
    let cur = '', inQ = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') {
        if (inQ && i + 1 < line.length && line[i + 1] === '"') { cur += '"'; i++; }
        else inQ = !inQ;
      } else if (ch === ',' && !inQ) {
        result.push(cur); cur = '';
      } else {
        cur += ch;
      }
    }
    result.push(cur);
    return result;
  }

  // ---- Propostas ----
  // Fonte prim├íria: dados reais (duocrm-quotes). Fallback: propostas geradas neste CRM.
  const getPropostas = () => {
    const reais = readRealQuotes();
    if (reais.length) return reais;
    const demo = load(KEY_PROP, []);
    return demo.map(p => { normalizeMidia(p); return p; });
  };
  const savePropostas = (arr) => save(KEY_PROP, arr);
  function nextId() {
    let seq = load(KEY_SEQ, 1100) + 1;
    save(KEY_SEQ, seq);
    return 'PROP-' + seq;
  }

  // Grava um array (j├í no formato interno) de volta na chave real, preservando campos originais.
  function persistReal(propostas) {
    const originais = (() => { const r = load(KEY_REAL, []); return Array.isArray(r) ? r : (r.quotes || []); })();
    const byId = {}; originais.forEach(o => { byId[o.id ?? o.quoteNumber ?? o.proposalId] = o; });
    const out = propostas.map(p => {
      const orig = byId[p.id] || {};
      // status interno -> ingl├¬s do app antigo (won/sent/negotiation/new/lost)
      const rev = { aberto: 'new', precificacao: 'quoting', enviada: 'sent', negociacao: 'negotiation', ganho: 'won', perdido: 'lost' };
      const valor = p.itens.reduce((s, it) => s + it.preco * it.qtd, 0);
      // Preserva TODOS os campos originais e atualiza apenas o essencial.
      return {
        ...orig,
        id: p.id,
        clientName: p.cliente,
        projectName: p.projeto || orig.projectName || p.categoria || '',
        value: valor,
        status: rev[p.status] || 'new',
        createdAt: p.criadoEm,
        updatedAt: p.atualizadoEm,
        itens: p.itens,
        motivo_perda: p.motivo_perda || orig.motivo_perda || '',
        lossReason: p.motivo_perda || orig.lossReason || null,
        atividades: Array.isArray(p.atividades) ? p.atividades : (orig.atividades || []),
        emissoes: Array.isArray(p.emissoes) ? p.emissoes : (orig.emissoes || []),
        foto_produto: p.foto_produto || orig.foto_produto || '',
        descricao_tecnica: p.descricao_tecnica || orig.descricao_tecnica || '',
        last_interaction_date: p.last_interaction_date || orig.last_interaction_date || p.atualizadoEm || orig.updatedAt || new Date().toISOString(),
        data_movimentacao: p.data_movimentacao || orig.data_movimentacao || p.atualizadoEm || orig.updatedAt || new Date().toISOString(),
      };
    });
    save(KEY_REAL, out);
  }

  // GARANTE que foto_produto e descricao_tecnica vivam na RAIZ da negocia├º├úo
  // (fonte ├║nica/unificada) e tamb├®m espelhadas no item[0], independentemente
  // de onde a proposta foi criada (gerador ou card do funil).
  function normalizeMidia(p) {
    if (!p || !Array.isArray(p.itens)) return p;
    const i0 = p.itens[0] || {};
    p.foto_produto = p.foto_produto || i0.foto || '';
    p.descricao_tecnica = p.descricao_tecnica || i0.descricao || '';
    // espelha de volta no item[0] para qualquer leitor baseado em itens
    if (p.itens[0]) {
      p.itens[0].foto = p.itens[0].foto || p.foto_produto;
      p.itens[0].descricao = p.itens[0].descricao || p.descricao_tecnica;
    }
    return p;
  }

  function addProposta(p) {
    p.id = nextId();
    p.criadoEm = new Date().toISOString();
    p.atualizadoEm = p.criadoEm;
    p.last_interaction_date = p.criadoEm;
    p.data_movimentacao = p.criadoEm;
    normalizeMidia(p);
    if (hasRealData()) { const arr = getPropostas(); arr.push(p); persistReal(arr); }
    else { const arr = load(KEY_PROP, []); arr.push(p); savePropostas(arr); }
    markDirty(p);
    return p;
  }
  // status: novo status; motivo: obrigat├│rio quando status === 'perdido'
  function updateStatus(id, status, motivo) {
    const arr = getPropostas();
    const p = arr.find(x => x.id === id);
    if (p) {
      p.status = status;
      const now = new Date().toISOString();
      p.atualizadoEm = now;
      p.last_interaction_date = now;   // reseta cad├¬ncia de follow-up
      p.data_movimentacao = now;       // vai para o topo da coluna de destino
      if (status === 'perdido') { p.motivo_perda = motivo || p.motivo_perda || 'N├úo informado'; }
      if (hasRealData()) persistReal(arr); else savePropostas(arr);
    }
    markDirty(p);
    return p;
  }
  function deleteProposta(id) {
    const arr = getPropostas().filter(x => x.id !== id);
    if (hasRealData()) persistReal(arr); else savePropostas(arr);
    remote.remove(id);
  }

  // Edi├º├úo direta de uma proposta (sem refazer o fluxo comercial).
  // campos: { cliente, contato, projeto, categoria, validade, prazo, pagamento, itens }
  function updateProposta(id, campos) {
    const arr = getPropostas();
    const p = arr.find(x => x.id === id);
    if (!p) return null;
    const allow = ['cliente', 'contato', 'projeto', 'categoria', 'validade', 'prazo', 'pagamento', 'itens', 'motivo_perda', 'foto_produto', 'descricao_tecnica'];
    allow.forEach(k => {
      if (campos[k] !== undefined) {
        if (k === 'itens' && Array.isArray(campos.itens)) p.itens = campos.itens;
        else p[k] = campos[k];
      }
    });
    normalizeMidia(p);
    p.atualizadoEm = new Date().toISOString();
    if (hasRealData()) persistReal(arr); else savePropostas(arr);
    markDirty(p);
    return p;
  }

  // ---- Atividades (timeline da negocia├º├úo) ----
  function getAtividades(id) {
    const p = getPropostas().find(x => x.id === id);
    return (p && Array.isArray(p.atividades)) ? p.atividades : [];
  }
  // Adiciona uma atividade ├á negocia├º├úo e atualiza "atualizadoEm".
  function addAtividade(id, atividade) {
    const arr = getPropostas();
    const p = arr.find(x => x.id === id);
    if (!p) return null;
    if (!Array.isArray(p.atividades)) p.atividades = [];
    const a = {
      id: 'ATV-' + Date.now().toString(36),
      tipo: atividade.tipo || 'Nota',
      titulo: (atividade.titulo || '').trim(),
      descricao: (atividade.descricao || '').trim(),
      criadoEm: new Date().toISOString(),
    };
    p.atividades.unshift(a);
    p.atualizadoEm = new Date().toISOString();
    p.last_interaction_date = p.atualizadoEm;  // registro de atividade = follow-up
    if (hasRealData()) persistReal(arr); else savePropostas(arr);
    markDirty(p);
    return a;
  }

  // ---- Hist├│rico de Propostas Emitidas ----
  function getEmissoes(id) {
    const p = getPropostas().find(x => x.id === id);
    return (p && Array.isArray(p.emissoes)) ? p.emissoes : [];
  }
  // Registra uma emiss├úo de PDF (data, n├║mero da cota├º├úo e tipo).
  function registrarEmissao(id, modo) {
    const arr = getPropostas();
    const p = arr.find(x => x.id === id);
    if (!p) return null;
    if (!Array.isArray(p.emissoes)) p.emissoes = [];
    const tipos = modo === 'tecnica' ? 'T├®cnica'
      : modo === 'comercial' ? 'Comercial'
        : 'T├®cnica e Comercial';
    const e = {
      id: 'EMI-' + Date.now().toString(36),
      cotacao: p.id,
      tipo: tipos,
      modo: modo || 'ambas',
      data: new Date().toISOString(),
    };
    p.emissoes.unshift(e);
    p.atualizadoEm = new Date().toISOString();
    if (hasRealData()) persistReal(arr); else savePropostas(arr);
    markDirty(p);
    return e;
  }

  // =========================================================
  // CLIENTES (Parceiros)
  // =========================================================
  const KEY_CLIENTS = 'energiza_clients';
const CLIENTS_TABLE = 'clients';
const NFE_IMPORTS_TABLE = 'nfe_imports';
const PRODS_TABLE = 'products';

  function getClients() { return load(KEY_CLIENTS, []); }
  function saveClients(arr) { save(KEY_CLIENTS, arr); }

  async function upsertClient(client) {
    const arr = getClients();
    if (client.id) {
      const i = arr.findIndex(x => x.id === client.id);
      if (i >= 0) { arr[i] = { ...arr[i], ...client }; } else { arr.push(client); }
    } else {
      client.id = 'CLI-' + Date.now().toString(36).toUpperCase();
      arr.push(client);
    }
    saveClients(arr);
    // Sync to Supabase
    if (remote.ready()) {
      const row = {
        id: String(client.id),
        name: client.name || '',
        razaoSocial: client.razaoSocial || '',
        cnpj: client.cnpj || '',
        email: client.email || '',
        phone: client.phone || '',
        address: client.address || '',
        externalCode: client.externalCode || '',
        observations: client.observations || '',
        lastSale: client.lastSale || '',
        totalSpent: client.totalSpent || 0,
        salesHistory: client.salesHistory || [],
        created_at: client.created_at || new Date().toISOString(),
        user_id: getCurrentUser().id,
      };
      const { error } = await window.supabaseClient.from(CLIENTS_TABLE).upsert(row, { onConflict: 'id' });
      if (error) console.warn('[Supabase] clients upsert falhou:', error.message);
    }
    return client;
  }

  async function deleteClient(id) {
    const arr = getClients().filter(x => x.id !== id);
    saveClients(arr);
    if (remote.ready()) {
      try {
        let delQuery = window.supabaseClient.from(CLIENTS_TABLE).delete().eq('id', id);
        if (!isAdmin()) delQuery = delQuery.eq('user_id', getCurrentUser().id);
        const { error } = await delQuery;
        if (error) console.warn('[Supabase] delete client falhou:', error.message);
      } catch (e) { console.warn('[Supabase] delete client erro:', e); }
    }
  }

  // Importa CSV de clientes.
  // Colunas esperadas: Nome_Fantasia,Razao_Social,CNPJ,Email,Telefone,Endereco,Codigo_Externo,Observacoes,Ultima_Venda,Total_Gasto,Quantidade_Vendas,Data_Criacao
  function importClientsCsv(text) {
    const lines = text.trim().split(/\r?\n/);
    if (lines.length < 2) throw new Error('CSV deve ter cabe├ºalho + pelo menos 1 linha.');
    const heads = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, '').toLowerCase());
    const colMap = {
      nome_fantasia: 'name', razao_social: 'razaoSocial',
      cnpj: 'cnpj', email: 'email', telefone: 'phone',
      endereco: 'address', codigo_externo: 'externalCode',
      observacoes: 'observations', ultima_venda: 'lastSale',
      total_gasto: 'totalSpent', quantidade_vendas: null,
      data_criacao: 'created_at',
    };
    const imported = [];
    for (let i = 1; i < lines.length; i++) {
      const vals = parseCsvLine(lines[i]);
      if (vals.length < 2) continue;
      const row = {};
      heads.forEach((h, j) => row[h] = (vals[j] || '').trim().replace(/^"|"$/g, ''));
      if (!row.nome_fantasia) continue;
      const client = {};
      Object.entries(colMap).forEach(([csvKey, dbKey]) => {
        if (dbKey === null) return; // skip quantidade_vendas
        client[dbKey] = row[csvKey] || '';
      });
      client.totalSpent = parseFloat(client.totalSpent) || 0;
      client.created_at = client.created_at || new Date().toISOString();
      client.salesHistory = [];
      // Generate sales history rows if quantidade_vendas > 0
      const qtdVendas = parseInt(row.quantidade_vendas) || 0;
      if (qtdVendas > 0) {
        for (let v = 0; v < Math.min(qtdVendas, 50); v++) {
          client.salesHistory.push({
            id: 'CSV-' + i + '-' + v,
            date: client.lastSale || '',
            item: 'Importado via CSV',
            quantity: 1, unitPrice: 0, total: 0,
            nfNumber: '', details: '',
            linkedPurchaseNf: '', linkedQuoteId: '', linkedOrderId: '',
            isService: false,
          });
        }
      }
      imported.push(client);
    }
    if (!imported.length) throw new Error('Nenhum cliente encontrado no CSV.');
    // Merge with existing (by cnpj or name match)
    const existing = getClients();
    const byCnpj = {}; existing.forEach(c => { if (c.cnpj) byCnpj[c.cnpj] = c; });
    imported.forEach(c => {
      const match = c.cnpj ? byCnpj[c.cnpj] : existing.find(x => x.name === c.name);
      if (match) {
        Object.assign(match, c, { id: match.id });
      } else {
        c.id = 'CLI-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 5);
        existing.push(c);
      }
    });
    saveClients(existing);
    return imported.length;
  }

  // =========================================================
  // NF-e XML Import & Price History
  // =========================================================
  const KEY_PRICE_HISTORY = 'energiza_price_history';
  const KEY_NFE_IMPORTS = 'energiza_nfe_imports';

  function getPriceHistory() {
    // 1) Reconstroi do salesHistory dos clientes (fonte principal)
    const fromClients = [];
    const clients = getClients();
    const seen = new Set();
    clients.forEach(c => {
      (c.salesHistory || []).forEach(s => {
        const id = s.id || (s.productCode + '-' + s.nfNumber);
        if (seen.has(id)) return;
        seen.add(id);
        fromClients.push({
          id,
          productCode: s.productCode || '',
          productName: s.item || '',
          ncm: s.ncm || '',
          cfop: s.cfop || '',
          nfNumber: s.nfNumber || '',
          date: s.date || '',
          supplierName: s.supplierName || '',
          supplierCnpj: s.supplierCnpj || '',
          clientCnpj: c.cnpj || '',
          quantity: s.quantity || 0,
          unitPrice: s.unitPrice || 0,
          total: s.total || 0,
        });
      });
    });

    // 2) Se vazio, tenta o cache consolidado das NF-e (populado por syncProductsFromNfeImports)
    if (!fromClients.length) {
      const cached = load(KEY_PRICE_HISTORY, []);
      if (cached.length) return cached;
    }

    return fromClients;
  }

  function getNfeImports() {
    // 1) Tenta localStorage cache (populado pelo pull do Supabase ou import local)
    const cached = load(KEY_NFE_IMPORTS, []);
    if (cached.length > 0) return cached;

    // 2) Fallback: reconstr├│i do salesHistory dos clientes
    const clients = getClients();
    const nfMap = {};
    clients.forEach(c => {
      (c.salesHistory || []).forEach(s => {
        if (!s.nfNumber) return;
        if (!nfMap[s.nfNumber]) {
          nfMap[s.nfNumber] = {
            nfId: s.nfNumber,
            nfNumber: s.nfNumber.includes('-') ? s.nfNumber.split('-')[0] : s.nfNumber,
            serie: s.nfNumber.includes('-') ? s.nfNumber.split('-')[1] : '',
            date: s.date || '',
            supplierName: s.supplierName || '',
            supplierCnpj: s.supplierCnpj || '',
            clientName: c.name || '',
            clientCnpj: c.cnpj || '',
            productCount: 0,
            status: 'sincronizado',
            erro: null,
          };
        }
        nfMap[s.nfNumber].productCount++;
      });
    });
    return Object.values(nfMap).sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  }

  // Parses a single NF-e XML string, returns parsed invoice data.
  // Handles optional namespace-prefixed tags (e.g. `nfe:` prefix).
  function parseNfeXml(xmlText) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(xmlText, 'text/xml');

    // Helpers namespace-agnostic (NF-e usa xmlns="http://www.portalfiscal.inf.br/nfe")
    function findOne(parent, tagName) {
      const list = parent.getElementsByTagNameNS('*', tagName);
      return list.length > 0 ? list[0] : null;
    }
    function findAll(parent, tagName) {
      return Array.from(parent.getElementsByTagNameNS('*', tagName));
    }
    function txt(base, ...queries) {
      for (const q of queries) {
        const parts = q.split(' ');
        let el = base;
        for (const p of parts) {
          const found = el.getElementsByTagNameNS('*', p);
          if (!found.length) { el = null; break; }
          el = found[0];
        }
        if (el && el !== base) return el.textContent.trim();
      }
      return '';
    }

    // Locate infNFe
    const infNFe = findOne(doc, 'infNFe');
    if (!infNFe) throw new Error('XML n├úo cont├®m tag infNFe. Verifique se ├® um arquivo NF-e v├ílido.');

    const nNF = txt(infNFe, 'ide nNF', 'nNF');
    const serie = txt(infNFe, 'ide serie', 'serie');
    const dhEmi = txt(infNFe, 'ide dhEmi', 'ide dEmi', 'dhEmi', 'dEmi');
    const emitCNPJ = txt(infNFe, 'emit CNPJ');
    const emitNome = txt(infNFe, 'emit xNome');
    const destCNPJ = txt(infNFe, 'dest CNPJ') || txt(infNFe, 'dest CPF');
    const destNome = txt(infNFe, 'dest xNome');

    // Parse addresses
    function addrStr(base, prefix) {
      const rua = txt(base, prefix + ' xLgr');
      const nro = txt(base, prefix + ' nro');
      const bairro = txt(base, prefix + ' xBairro');
      const cidade = txt(base, prefix + ' xMun');
      const uf = txt(base, prefix + ' UF');
      return [rua, nro].filter(Boolean).join(', ') + (bairro ? ' - ' + bairro : '') + (cidade ? ' - ' + cidade : '') + (uf ? '/' + uf : '');
    }
    const destEndereco = addrStr(infNFe, 'dest enderDest');
    const emitEndereco = addrStr(infNFe, 'emit enderEmit');

    // Parse products
    const dets = findAll(infNFe, 'det');
    const products = dets.map(det => {
      const cProd = txt(det, 'prod cProd', 'cProd');
      const xProd = txt(det, 'prod xProd', 'xProd');
      const NCM = txt(det, 'prod NCM', 'NCM');
      const CFOP = txt(det, 'prod CFOP', 'CFOP');
      const qCom = parseFloat(txt(det, 'prod qCom', 'qCom').replace(',', '.')) || 0;
      const vUnCom = parseFloat(txt(det, 'prod vUnCom', 'vUnCom').replace(',', '.')) || 0;
      const vProd = parseFloat(txt(det, 'prod vProd', 'vProd').replace(',', '.')) || 0;
      return (cProd || xProd) ? { codigo: cProd || '', nome: xProd || '', ncm: NCM || '', cfop: CFOP || '', quantidade: qCom, unitPrice: vUnCom, total: vProd } : null;
    }).filter(Boolean);

    if (!products.length) throw new Error('Nenhum produto encontrado na NF-e.');

    return {
      nfNumber: nNF, serie, date: dhEmi,
      supplierCnpj: emitCNPJ, supplierName: emitNome,
      clientCnpj: destCNPJ, clientName: destNome,
      clientAddress: destEndereco,
      supplierAddress: emitEndereco,
      products,
    };
  }

  // Imports one or more NF-e XML texts.
  // For each invoice: finds the client by CNPJ, appends to salesHistory,
  // updates totalSpent/lastSale, and records each product in priceHistory.
  async function importNfeXml(xmlTexts) {
    const nfeList = Array.isArray(xmlTexts) ? xmlTexts : [xmlTexts];
    console.log('[NF-e] importNfeXml recebeu', nfeList.length, 'XML(s), tamanhos:', nfeList.map(x => (x || '').length));
    const clients = getClients();
    const priceHist = getPriceHistory();
    const nfeImports = getNfeImports();
    let totalItems = 0;
    const updatedClients = new Set();

    nfeList.forEach((xml, idx) => {
      let parsed;
      try {
        if (!xml || xml.length < 50) throw new Error('Conte├║do XML vazio ou muito curto (' + (xml || '').length + ' bytes)');
        parsed = parseNfeXml(xml);
      }
      catch (e) { throw new Error('XML ' + (idx + 1) + ': ' + e.message); }

      const nfId = parsed.nfNumber + (parsed.serie ? '-' + parsed.serie : '');
      if (nfeImports.some(x => x.nfId === nfId)) { console.log('[NF-e] duplicata ignorada:', nfId); return; }
      console.log('[NF-e] XML', idx, 'ÔåÆ NF:', nfId, '| emit:', parsed.supplierName, '| dest:', parsed.clientName, '| produtos:', parsed.products.length);

      // Find client only by CNPJ ÔÇö nunca por nome, pois unidades diferentes
      // podem ter o mesmo nome fantasia mas CNPJs distintos (ex: IMED)
      const clientCnpj = parsed.clientCnpj.replace(/\D/g, '');
      let client = clientCnpj ? clients.find(c => (c.cnpj || '').replace(/\D/g, '') === clientCnpj) : null;
      // If still not found, create a new client record
      if (!client) {
        client = {
          id: 'CLI-NFE-' + Date.now().toString(36).toUpperCase() + '-' + idx,
          name: parsed.clientName || 'Cliente NF-e ' + nfId,
          cnpj: parsed.clientCnpj,
          razaoSocial: parsed.clientName || '',
          email: '', phone: '', address: parsed.clientAddress || '', externalCode: '',
          observations: 'Importado automaticamente de NF-e',
          lastSale: parsed.date,
          totalSpent: 0,
          salesHistory: [],
          created_at: new Date().toISOString(),
        };
        clients.push(client);
      }
      updatedClients.add(client.id);

      // Also find/ensure supplier as a client record ÔÇö apenas por CNPJ
      const suppCnpj = parsed.supplierCnpj.replace(/\D/g, '');
      let supplier = suppCnpj ? clients.find(c => (c.cnpj || '').replace(/\D/g, '') === suppCnpj) : null;
      if (!supplier && parsed.supplierName) {
        supplier = {
          id: 'CLI-NFE-SUP-' + Date.now().toString(36).toUpperCase() + '-' + idx,
          name: parsed.supplierName,
          cnpj: parsed.supplierCnpj,
          razaoSocial: parsed.supplierName || '',
          email: '', phone: '', address: parsed.supplierAddress || '', externalCode: '',
          observations: 'Fornecedor (importado NF-e)',
          lastSale: '', totalSpent: 0, salesHistory: [],
          created_at: new Date().toISOString(),
        };
        clients.push(supplier);
      }
      if (supplier) updatedClients.add(supplier.id);

      // Add purchase to client's salesHistory
      parsed.products.forEach((prod, pi) => {
        const saleEntry = {
          id: 'NFE-' + nfId + '-' + pi,
          date: parsed.date,
          item: prod.nome,
          quantity: prod.quantidade,
          unitPrice: prod.unitPrice,
          total: prod.total,
          nfNumber: nfId,
          productCode: prod.codigo || '',
          ncm: prod.ncm || '',
          cfop: prod.cfop || '',
          supplierName: parsed.supplierName || '',
          supplierCnpj: parsed.supplierCnpj || '',
          details: 'C├│digo: ' + prod.codigo + ' | NCM: ' + prod.ncm + ' | CFOP: ' + prod.cfop,
          linkedPurchaseNf: nfId,
          linkedQuoteId: '', linkedOrderId: '',
          isService: prod.ncm === '' || prod.cfop.startsWith('5') || false,
        };
        client.salesHistory.push(saleEntry);

        // Record in priceHistory
        priceHist.push({
          id: 'PH-' + Date.now().toString(36).toUpperCase() + '-' + totalItems,
          productCode: prod.codigo,
          productName: prod.nome,
          ncm: prod.ncm,
          cfop: prod.cfop,
          nfNumber: nfId,
          date: parsed.date,
          supplierCnpj: parsed.supplierCnpj,
          supplierName: parsed.supplierName,
          clientCnpj: parsed.clientCnpj,
          quantity: prod.quantidade,
          unitPrice: prod.unitPrice,
          total: prod.total,
        });
        totalItems++;
      });

      // Update client totals
      const nfTotal = parsed.products.reduce((s, p) => s + p.total, 0);
      client.totalSpent = (client.totalSpent || 0) + nfTotal;
      if (parsed.date && (!client.lastSale || parsed.date > client.lastSale)) client.lastSale = parsed.date;

      // Record import metadata with product line items
      nfeImports.push({
        nfId,
        nfNumber: parsed.nfNumber,
        serie: parsed.serie,
        date: parsed.date,
        supplierName: parsed.supplierName,
        supplierCnpj: parsed.supplierCnpj,
        clientName: parsed.clientName,
        clientCnpj: parsed.clientCnpj,
        productCount: parsed.products.length,
        importedAt: new Date().toISOString(),
        items: parsed.products.map(p => ({
          codigo: p.codigo || '',
          nome: p.nome || '',
          ncm: p.ncm || '',
          cfop: p.cfop || '',
          quantidade: p.quantidade || 0,
          unitPrice: p.unitPrice || 0,
          total: p.total || 0,
        })),
      });
    });

    // ÔöÇÔöÇÔöÇ Salva cache local ÔöÇÔöÇÔöÇ
    saveClients(clients);
    save(KEY_PRICE_HISTORY, priceHist);
    save(KEY_NFE_IMPORTS, nfeImports);

    // ÔöÇÔöÇÔöÇ Grava├º├úo direta no Supabase (fonte prim├íria) ÔöÇÔöÇÔöÇ
    if (remote.ready()) {
      try {
        // 1) Upsert clientes alterados
        for (const id of updatedClients) {
          const c = clients.find(x => x.id === id);
          if (!c) continue;
          const row = {
            id: String(c.id), name: c.name || '', razaoSocial: c.razaoSocial || '',
            cnpj: c.cnpj || '', email: c.email || '', phone: c.phone || '',
            address: c.address || '',
            observations: c.observations || '', lastSale: c.lastSale || '',
            totalSpent: c.totalSpent || 0,
            salesHistory: Array.isArray(c.salesHistory) ? c.salesHistory : [],
            user_id: getCurrentUser().id,
          };
          const { error: cliErr } = await window.supabaseClient
            .from(CLIENTS_TABLE).upsert(row, { onConflict: 'id' });
          if (cliErr) console.error('[Supabase] sync client ERRO:', cliErr.message, cliErr.code, cliErr.details);
        }

        // 2) Upsert TODOS os itens de produto de cada NF-e na tabela products
        for (const nf of nfeImports) {
          const items = Array.isArray(nf.items) ? nf.items : [];
          for (const it of items) {
            if (!it.codigo && !it.nome) continue;
            const prodRow = {
              code: it.codigo || it.nome,
              name: it.nome || 'ÔÇö',
              ncm: it.ncm || '',
              last_price: it.unitPrice || 0,
              total_bought: it.quantidade || 0,
              supplier_name: nf.supplierName || '',
              nf_number: nf.nfNumber || '',
              user_id: getCurrentUser().id,
            };
            const { error: prodErr } = await window.supabaseClient
              .from(PRODS_TABLE).upsert(prodRow, { onConflict: 'code' });
            if (prodErr) console.error('[Supabase] upsert product ERRO:', prodErr.message, prodErr.code);
          }
        }

        // 3) Push nfe_imports
        const rows = nfeImports.map(n => ({
          nfId: n.nfId,
          nfNumber: n.nfNumber || '',
          serie: n.serie || '',
          date: n.date || '',
          supplierName: n.supplierName || '',
          supplierCnpj: n.supplierCnpj || '',
          clientName: n.clientName || '',
          clientCnpj: n.clientCnpj || '',
          productCount: n.productCount || 0,
          importedAt: n.importedAt || new Date().toISOString(),
          items: Array.isArray(n.items) ? n.items : [],
        }));
        await remote.pushNfeImports(rows);

        // 4) Consolida produtos no price history cache
        remote.syncProductsFromNfeImports();
      } catch (e) { console.error('[Supabase] sync pos-import exce├º├úo:', e); }
    }

    return totalItems;
  }

  // ---- helpers ----
  const totalProposta = (p) => (p.itens || []).reduce((s, i) => s + i.preco * i.qtd, 0);

  function resetPartnerData() {
    try {
      // Limpa localStorage
      localStorage.clear();
    } catch (e) { console.warn('[resetPartnerData] erro localStorage:', e); }
    // Limpa Supabase (fire-and-forget ÔÇö n├úo bloqueia)
    if (remote.ready()) {
      const tables = [NFE_IMPORTS_TABLE, PRODS_TABLE, CLIENTS_TABLE, 'negociacoes'];
      tables.forEach(t => {
        // Deleta todas as linhas da tabela (filtro always-true)
        window.supabaseClient.from(t).delete().neq('id', '-1').then(r => {
          if (r.error) console.warn('[resetPartnerData] delete', t, 'falhou:', r.error.message);
          else console.log('[resetPartnerData] delete', t, 'OK ÔÇö', r.count || '?', 'linhas');
        }).catch(e => console.warn('[resetPartnerData] delete', t, 'exce├º├úo:', e));
      });
    }
  }

  return {
    STATUS, STATUS_ORDER, CATEGORIAS,
    ensureSeed, seedDemoPropostas,
    getProdutos, upsertProduto, deleteProduto,
    getPropostas, addProposta, updateStatus, deleteProposta, updateProposta,
    getAtividades, addAtividade,
    getEmissoes, registrarEmissao,
    totalProposta,
    hasRealData, readRealQuotes, importBackup, exportBackup, importCsv,
    remote, markDirty,
    getClients, upsertClient, deleteClient, importClientsCsv, CLIENTS_TABLE, NFE_IMPORTS_TABLE, PRODS_TABLE,
    importNfeXml, parseNfeXml, getPriceHistory, getNfeImports,
    syncProductsFromNfeImports: remote.syncProductsFromNfeImports.bind(remote),
    resetPartnerData,
  };
})();

/**
 * Sistema de Auditoria ÔÇö ENERGIZA CRM
 *
 * Registra todas as a├º├Áes de seguran├ºa e operacionais.
 * Armazena em localStorage e sincroniza com Supabase quando dispon├¡vel.
 *
 * Padr├úo: Window Global (Scripts Cl├íssicos + IIFE)
 */

window.Audit = (() => {
  'use strict';

  const AUDIT_KEY = 'energiza_audit';
  const MAX_ENTRIES = 1000;
  const SUPABASE_TABLE = 'audit_logs';

  // ÔöÇÔöÇÔöÇ A├º├Áes de Auditoria ÔöÇÔöÇÔöÇ
  const ACTIONS = {
    // Autentica├º├úo
    LOGIN_SUCCESS: 'login_success',
    LOGIN_FAILED: 'login_failed',
    LOGIN_ERROR: 'login_error',
    LOGOUT: 'logout',
    SESSION_EXPIRED: 'session_expired',
    PASSWORD_RESET: 'password_reset_requested',
    PASSWORD_CHANGED: 'password_changed',

    // Usu├írios
    USER_CREATED: 'user_created',
    USER_UPDATED: 'user_updated',
    USER_DELETED: 'user_deleted',
    PROFILE_CHANGED: 'profile_changed',
    PERMISSION_CHANGED: 'permission_changed',

    // Dados
    DATA_CREATED: 'data_created',
    DATA_UPDATED: 'data_updated',
    DATA_DELETED: 'data_deleted',
    DATA_IMPORTED: 'data_imported',
    DATA_EXPORTED: 'data_exported',

    // Sistema
    SYSTEM_ERROR: 'system_error',
    SYNC_STARTED: 'sync_started',
    SYNC_COMPLETED: 'sync_completed',
    SYNC_FAILED: 'sync_failed',
  };

  // ÔöÇÔöÇÔöÇ Log Principal ÔöÇÔöÇÔöÇ
  function log(action, data) {
    const entry = {
      id: _generateId(),
      timestamp: new Date().toISOString(),
      action: action,
      userId: _getUserId(),
      userEmail: _getUserEmail(),
      data: data || {},
      ip: null,
      userAgent: navigator.userAgent,
      screen: _getScreenInfo(),
    };

    // Tentar obter IP (pode falhar por CORS)
    _fetchIP().then(ip => {
      entry.ip = ip;
      _persistEntry(entry);
    }).catch(() => {
      _persistEntry(entry);
    });

    return entry;
  }

  // ÔöÇÔöÇÔöÇ Persistir Entrada ÔöÇÔöÇÔöÇ
  function _persistEntry(entry) {
    // Salvar em localStorage
    _saveToLocalStorage(entry);

    // Sincronizar com Supabase (async, sem blocking)
    _syncToSupabase(entry);
  }

  // ÔöÇÔöÇÔöÇ LocalStorage ÔöÇÔöÇÔöÇ
  function _saveToLocalStorage(entry) {
    try {
      const logs = JSON.parse(localStorage.getItem(AUDIT_KEY) || '[]');
      logs.push(entry);

      // Manter apenas as ├║ltimas MAX_ENTRIES
      if (logs.length > MAX_ENTRIES) {
        logs.splice(0, logs.length - MAX_ENTRIES);
      }

      localStorage.setItem(AUDIT_KEY, JSON.stringify(logs));
    } catch (_) {
      // localStorage full or unavailable
    }
  }

  // ÔöÇÔöÇÔöÇ Supabase Sync ÔöÇÔöÇÔöÇ
  async function _syncToSupabase(entry) {
    if (!window.supabaseClient) return;

    try {
      await window.supabaseClient
        .from(SUPABASE_TABLE)
        .insert({
          id: entry.id,
          timestamp: entry.timestamp,
          action: entry.action,
          user_id: entry.userId,
          user_email: entry.userEmail,
          data: entry.data,
          ip: entry.ip,
          user_agent: entry.userAgent,
          screen: entry.screen,
        });
    } catch (_) {
      // Silently fail ÔÇö audit in localStorage is fallback
    }
  }

  // ÔöÇÔöÇÔöÇ Buscar Logs ÔöÇÔöÇÔöÇ
  function getLogs(filters) {
    let logs = JSON.parse(localStorage.getItem(AUDIT_KEY) || '[]');

    if (filters) {
      if (filters.action) {
        logs = logs.filter(l => l.action === filters.action);
      }
      if (filters.userId) {
        logs = logs.filter(l => l.userId === filters.userId);
      }
      if (filters.startDate) {
        logs = logs.filter(l => new Date(l.timestamp) >= new Date(filters.startDate));
      }
      if (filters.endDate) {
        logs = logs.filter(l => new Date(l.timestamp) <= new Date(filters.endDate));
      }
      if (filters.limit) {
        logs = logs.slice(-filters.limit);
      }
    }

    return logs;
  }

  // ÔöÇÔöÇÔöÇ Buscar Logs de Seguran├ºa ÔöÇÔöÇÔöÇ
  function getSecurityLogs(limit) {
    const securityActions = [
      ACTIONS.LOGIN_SUCCESS,
      ACTIONS.LOGIN_FAILED,
      ACTIONS.LOGIN_ERROR,
      ACTIONS.LOGOUT,
      ACTIONS.SESSION_EXPIRED,
      ACTIONS.PASSWORD_RESET,
      ACTIONS.PASSWORD_CHANGED,
      ACTIONS.PROFILE_CHANGED,
      ACTIONS.PERMISSION_CHANGED,
    ];

    return getLogs({ limit: limit || 100 }).filter(l =>
      securityActions.includes(l.action)
    );
  }

  // ÔöÇÔöÇÔöÇ Exportar Logs ÔöÇÔöÇÔöÇ
  function exportLogs(format) {
    const logs = getLogs();

    if (format === 'csv') {
      return _exportAsCSV(logs);
    }

    return JSON.stringify(logs, null, 2);
  }

  function _exportAsCSV(logs) {
    if (logs.length === 0) return '';

    const headers = ['Timestamp', 'Action', 'User ID', 'Email', 'IP', 'Data'];
    const rows = logs.map(l => [
      l.timestamp,
      l.action,
      l.userId,
      l.userEmail,
      l.ip || 'N/A',
      JSON.stringify(l.data),
    ]);

    return [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
  }

  // ÔöÇÔöÇÔöÇ Limpar Logs ÔöÇÔöÇÔöÇ
  function clearLogs() {
    localStorage.removeItem(AUDIT_KEY);
  }

  // ÔöÇÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇ
  function _generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  function _getUserId() {
    if (typeof window.Auth !== 'undefined' && window.Auth.getUser()) {
      return window.Auth.getUser().id;
    }
    return 'anonymous';
  }

  function _getUserEmail() {
    if (typeof window.Auth !== 'undefined' && window.Auth.getUser()) {
      return window.Auth.getUser().email;
    }
    return 'anonymous';
  }

  function _getScreenInfo() {
    return {
      width: window.screen.width,
      height: window.screen.height,
      viewport: {
        width: window.innerWidth,
        height: window.innerHeight,
      },
    };
  }

  async function _fetchIP() {
    try {
      const response = await fetch('https://api.ipify.org?format=json', {
        signal: AbortSignal.timeout(2000),
      });
      const data = await response.json();
      return data.ip;
    } catch (_) {
      return null;
    }
  }

  // ÔöÇÔöÇÔöÇ API P├║blica ÔöÇÔöÇÔöÇ
  return {
    log: log,
    getLogs: getLogs,
    getSecurityLogs: getSecurityLogs,
    exportLogs: exportLogs,
    clearLogs: clearLogs,
    ACTIONS: ACTIONS,
  };
})();

/**
 * Servi├ºo de Autentica├º├úo ÔÇö ENERGIZA CRM
 *
 * Gerencia autentica├º├úo via Supabase Auth.
 * Mant├®m compatibilidade com localStorage como fallback.
 *
 * Padr├úo: Window Global (Scripts Cl├íssicos + IIFE)
 */

window.Auth = (() => {
  'use strict';

  const SESSION_KEY = 'energiza_session';
  const PROFILE_KEY = 'energiza_profile';
  const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutos
  const REFRESH_INTERVAL = 5 * 60 * 1000; // 5 minutos

  let _session = null;
  let _profile = null;
  let _refreshTimer = null;
  let _sessionTimer = null;
  let _onAuthChange = null;

  // ÔöÇÔöÇÔöÇ Perfis e Permiss├Áes ÔöÇÔöÇÔöÇ
  const PROFILES = {
    admin: {
      label: 'Administrador',
      permissions: ['all'],
      color: '#ef4444',
    },
    comercial: {
      label: 'Comercial',
      permissions: ['propostas', 'clientes', 'catalogo', 'relatorios'],
      color: '#3b82f6',
    },
    tecnico: {
      label: 'T├®cnico',
      permissions: ['catalogo', 'relatorios'],
      color: '#22c55e',
    },
    financeiro: {
      label: 'Financeiro',
      permissions: ['relatorios', 'financeiro'],
      color: '#f59e0b',
    },
    leitura: {
      label: 'Leitura',
      permissions: ['dashboard', 'relatorios'],
      color: '#6b7280',
    },
  };

  // ÔöÇÔöÇÔöÇ Inicializa├º├úo ÔöÇÔöÇÔöÇ
  function init(onAuthChange) {
    _onAuthChange = onAuthChange || function () {};

    // Restaurar sess├úo do localStorage
    _restoreSession();

    // Verificar sess├úo existente no Supabase
    if (window.supabaseClient) {
      _checkExistingSession();
    }

    // Iniciar refresh autom├ítico
    _startRefreshTimer();

    return this;
  }

  // ÔöÇÔöÇÔöÇ Login ÔöÇÔöÇÔöÇ
  async function login(email, password) {
    if (!window.supabaseClient) {
      return { success: false, error: 'Supabase client n├úo inicializado' };
    }

    try {
      const { data, error } = await window.supabaseClient.auth.signInWithPassword({
        email: email,
        password: password,
      });

      if (error) {
        _logSecurity('login_failed', { email: email, error: error.message });
        return { success: false, error: error.message };
      }

      _session = data.session;
      _profile = await _fetchProfile(data.user.id);

      _saveSession();
      _saveProfile();
      _resetSessionTimer();

      _logSecurity('login_success', {
        userId: data.user.id,
        email: data.user.email,
        profile: _profile ? _profile.role : 'unknown',
      });

      _onAuthChange({ user: data.user, session: _session, profile: _profile });

      return { success: true, user: data.user, session: _session, profile: _profile };
    } catch (err) {
      _logSecurity('login_error', { email: email, error: err.message });
      return { success: false, error: err.message };
    }
  }

  // ÔöÇÔöÇÔöÇ Logout ÔöÇÔöÇÔöÇ
  async function logout() {
    if (!window.supabaseClient) {
      _clearSession();
      _onAuthChange({ user: null, session: null, profile: null });
      return { success: true };
    }

    try {
      const { error } = await window.supabaseClient.auth.signOut();

      if (error) {
        console.warn('[Auth] Erro no logout Supabase:', error);
      }

      _logSecurity('logout', {
        userId: _session ? _session.user.id : null,
      });

      _clearSession();
      _onAuthChange({ user: null, session: null, profile: null });

      return { success: true };
    } catch (err) {
      console.warn('[Auth] Erro no logout:', err);
      _clearSession();
      _onAuthChange({ user: null, session: null, profile: null });
      return { success: true };
    }
  }

  // ÔöÇÔöÇÔöÇ Recupera├º├úo de Senha ÔöÇÔöÇÔöÇ
  async function resetPassword(email) {
    if (!window.supabaseClient) {
      return { success: false, error: 'Supabase client n├úo inicializado' };
    }

    try {
      const { error } = await window.supabaseClient.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin,
      });

      if (error) {
        return { success: false, error: error.message };
      }

      _logSecurity('password_reset_requested', { email: email });

      return { success: true };
    } catch (err) {
      return { success: false, error: err.message };
    }
  }

  // ÔöÇÔöÇÔöÇ Altera├º├úo de Senha ÔöÇÔöÇÔöÇ
  async function updatePassword(newPassword) {
    if (!window.supabaseClient) {
      return { success: false, error: 'Supabase client n├úo inicializado' };
    }

    try {
      const { error } = await window.supabaseClient.auth.updateUser({
        password: newPassword,
      });

      if (error) {
        return { success: false, error: error.message };
      }

      _logSecurity('password_changed', {
        userId: _session ? _session.user.id : null,
      });

      return { success: true };
    } catch (err) {
      return { success: false, error: err.message };
    }
  }

  // ÔöÇÔöÇÔöÇ Verificar Sess├úo ÔöÇÔöÇÔöÇ
  async function _checkExistingSession() {
    try {
      const { data: { session }, error } = await window.supabaseClient.auth.getSession();

      if (error) {
        console.warn('[Auth] Erro ao verificar sess├úo:', error);
        return;
      }

      if (session) {
        _session = session;
        _profile = await _fetchProfile(session.user.id);
        _saveSession();
        _saveProfile();
        _resetSessionTimer();
        _onAuthChange({ user: session.user, session: _session, profile: _profile });
      } else {
        _onAuthChange({ user: null, session: null, profile: null });
      }
    } catch (err) {
      console.warn('[Auth] Erro ao verificar sess├úo:', err);
    }
  }

  // ÔöÇÔöÇÔöÇ Buscar Perfil ÔöÇÔöÇÔöÇ
  async function _fetchProfile(userId) {
    if (!window.supabaseClient) return null;

    try {
      const { data, error } = await window.supabaseClient
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (error || !data) {
        // Criar perfil padr├úo se n├úo existir
        return await _createDefaultProfile(userId);
      }

      return data;
    } catch (err) {
      console.warn('[Auth] Erro ao buscar perfil:', err);
      return null;
    }
  }

  // ÔöÇÔöÇÔöÇ Criar Perfil Padr├úo ÔöÇÔöÇÔöÇ
  async function _createDefaultProfile(userId) {
    if (!window.supabaseClient) return null;

    try {
      const { data: { user } } = await window.supabaseClient.auth.getUser();
      if (!user) return null;

      const profile = {
        id: userId,
        name: user.email.split('@')[0],
        role: 'leitura',
        created_at: new Date().toISOString(),
      };

      const { data, error } = await window.supabaseClient
        .from('profiles')
        .upsert(profile, { onConflict: 'id' })
        .select()
        .single();

      if (error) {
        console.warn('[Auth] Erro ao criar perfil:', error);
        return profile;
      }

      return data;
    } catch (err) {
      console.warn('[Auth] Erro ao criar perfil:', err);
      return null;
    }
  }

  // ÔöÇÔöÇÔöÇ Refresh Token ÔöÇÔöÇÔöÇ
  async function _refreshSession() {
    if (!window.supabaseClient || !_session) return;

    try {
      const { data: { session }, error } = await window.supabaseClient.auth.getSession();

      if (error) {
        console.warn('[Auth] Erro ao refresh session:', error);
        _handleSessionExpired();
        return;
      }

      if (session) {
        _session = session;
        _saveSession();
        _resetSessionTimer();
      } else {
        _handleSessionExpired();
      }
    } catch (err) {
      console.warn('[Auth] Erro ao refresh session:', err);
      _handleSessionExpired();
    }
  }

  // ÔöÇÔöÇÔöÇ Sess├úo Expirada ÔöÇÔöÇÔöÇ
  function _handleSessionExpired() {
    _logSecurity('session_expired', {
      userId: _session ? _session.user.id : null,
    });

    _clearSession();
    _onAuthChange({ user: null, session: null, profile: null, expired: true });
  }

  // ÔöÇÔöÇÔöÇ Timer de Refresh ÔöÇÔöÇÔöÇ
  function _startRefreshTimer() {
    _stopRefreshTimer();
    _refreshTimer = setInterval(_refreshSession, REFRESH_INTERVAL);
  }

  function _stopRefreshTimer() {
    if (_refreshTimer) {
      clearInterval(_refreshTimer);
      _refreshTimer = null;
    }
  }

  // ÔöÇÔöÇÔöÇ Timer de Sess├úo ÔöÇÔöÇÔöÇ
  function _resetSessionTimer() {
    if (_sessionTimer) {
      clearTimeout(_sessionTimer);
    }
    _sessionTimer = setTimeout(_handleSessionExpired, SESSION_TIMEOUT);
  }

  // ÔöÇÔöÇÔöÇ Persist├¬ncia ÔöÇÔöÇÔöÇ
  function _saveSession() {
    try {
      localStorage.setItem(SESSION_KEY, JSON.stringify(_session));
    } catch (_) {
      // localStorage full or unavailable
    }
  }

  function _saveProfile() {
    try {
      localStorage.setItem(PROFILE_KEY, JSON.stringify(_profile));
    } catch (_) {
      // localStorage full or unavailable
    }
  }

  function _restoreSession() {
    try {
      const session = localStorage.getItem(SESSION_KEY);
      const profile = localStorage.getItem(PROFILE_KEY);
      if (session) _session = JSON.parse(session);
      if (profile) _profile = JSON.parse(profile);
    } catch (_) {
      _session = null;
      _profile = null;
    }
  }

  function _clearSession() {
    _session = null;
    _profile = null;
    _stopRefreshTimer();
    try {
      localStorage.removeItem(SESSION_KEY);
      localStorage.removeItem(PROFILE_KEY);
    } catch (_) {
      // localStorage unavailable
    }
  }

  // ÔöÇÔöÇÔöÇ Auditoria ÔöÇÔöÇÔöÇ
  function _logSecurity(action, data) {
    if (typeof window.Audit !== 'undefined') {
      window.Audit.log(action, data);
    }
  }

  // ÔöÇÔöÇÔöÇ Getters ÔöÇÔöÇÔöÇ
  function getUser() {
    return _session ? _session.user : null;
  }

  function getSession() {
    return _session;
  }

  function getProfile() {
    return _profile;
  }

  function isAuthenticated() {
    return !!_session && !!_session.user;
  }

  function hasPermission(permission) {
    if (!_profile) return false;
    const profileConfig = PROFILES[_profile.role];
    if (!profileConfig) return false;
    return profileConfig.permissions.includes('all') || profileConfig.permissions.includes(permission);
  }

  function getProfiles() {
    return PROFILES;
  }

  // ÔöÇÔöÇÔöÇ Atualizar Perfil ÔöÇÔöÇÔöÇ
  async function updateProfile(userId, updates) {
    if (!window.supabaseClient) {
      return { success: false, error: 'Supabase client n├úo inicializado' };
    }

    try {
      const { data, error } = await window.supabaseClient
        .from('profiles')
        .upsert({ id: userId, ...updates }, { onConflict: 'id' })
        .select()
        .single();

      if (error) {
        return { success: false, error: error.message };
      }

      if (userId === getUser()?.id) {
        _profile = data;
        _saveProfile();
      }

      return { success: true, profile: data };
    } catch (err) {
      return { success: false, error: err.message };
    }
  }

  // ÔöÇÔöÇÔöÇ Listar Usu├írios (Admin) ÔöÇÔöÇÔöÇ
  async function listUsers() {
    if (!window.supabaseClient || !hasPermission('all')) {
      return { success: false, error: 'Sem permiss├úo' };
    }

    try {
      const { data, error } = await window.supabaseClient
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        return { success: false, error: error.message };
      }

      return { success: true, users: data };
    } catch (err) {
      return { success: false, error: err.message };
    }
  }

  // ÔöÇÔöÇÔöÇ API P├║blica ÔöÇÔöÇÔöÇ
  return {
    init: init,
    login: login,
    logout: logout,
    resetPassword: resetPassword,
    updatePassword: updatePassword,
    getUser: getUser,
    getSession: getSession,
    getProfile: getProfile,
    isAuthenticated: isAuthenticated,
    hasPermission: hasPermission,
    getProfiles: getProfiles,
    updateProfile: updateProfile,
    listUsers: listUsers,
    PROFILES: PROFILES,
  };
})();

/* =========================================================
   TELA 2 ÔÇö Funil de Vendas (Kanban)
   Drag & drop + bot├Áes de mover + coluna "Perdidas/Canceladas"
   com modal obrigat├│rio de motivo (persistido em motivo_perda).
   ========================================================= */
(() => {
  let draggingId = null;
  let filterTerm = '';

  // T├¡tulos numerados das colunas (cad├¬ncia l├│gica do funil comercial).
  const COL_TITLES = {
    aberto: '1. Cota├º├úo em Aberto',
    precificacao: '2. Em Precifica├º├úo / Montagem',
    enviada: '3. Proposta Enviada',
    negociacao: '4. Em Negocia├º├úo',
    ganho: '5. Ganho / Faturado',
    perdido: '6. Perdidas / Canceladas',
  };

  // Motivos r├ípidos pr├®-definidos para a perda/cancelamento.
  const MOTIVOS = [
    'Pre├ºo acima do or├ºamento do cliente',
    'Concorrente venceu',
    'Cliente desistiu / sem verba',
    'Prazo de entrega invi├ível',
    'Sem retorno do cliente',
    'Especifica├º├úo t├®cnica n├úo atendida',
  ];

  // Calcula o est├ígio de follow-up com base em last_interaction_date (agora).
  function stageClass(p) {
    const t = p.last_interaction_date ? new Date(p.last_interaction_date).getTime() : 0;
    if (!t) return '';
    const dias = Math.floor((Date.now() - t) / 86400000);
    if (dias > 5) return 'alert-danger';
    if (dias > 3) return 'alert-warning';
    return '';
  }

  // Texto de acessibilidade para o alerta de inatividade (n├úo depende s├│ de cor).
  function alertTag(p) {
    const t = p.last_interaction_date ? new Date(p.last_interaction_date).getTime() : 0;
    if (!t) return '';
    const dias = Math.floor((Date.now() - t) / 86400000);
    if (dias <= 3) return '';
    return `ÔÜá ${dias} ${dias === 1 ? 'dia' : 'dias'} sem atualiza├º├úo`;
  }

  // Feedback de sucesso: brilho verde vibrante por 3s ap├│s follow-up.
  function flashCard(id) {
    const card = document.querySelector(`.kcard[data-id="${CSS.escape(id)}"]`);
    if (!card) return;
    card.classList.remove('alert-warning', 'alert-danger', 'kcard-glow-success');
    // for├ºa reflow para reiniciar a anima├º├úo
    void card.offsetWidth;
    card.classList.add('kcard-glow-success');
    setTimeout(() => card.classList.remove('kcard-glow-success'), 3000);
  }

  // Alerta visual vermelho para travas de seguran├ºa (ex: tentativa de avan├ºar sem valor).
  function flashError(id) {
    const card = document.querySelector(`.kcard[data-id="${CSS.escape(id)}"]`);
    if (!card) return;
    card.classList.add('kcard-flash-error');
    setTimeout(() => card.classList.remove('kcard-flash-error'), 1200);
  }

  function cardHtml(p) {
    const item = p.itens && p.itens[0] ? p.itens[0].nome + (p.itens.length > 1 ? ` +${p.itens.length - 1}` : '') : 'ÔÇö';
    const motivo = p.status === 'perdido' && p.motivo_perda
      ? `<div class="kcard-motivo">Ô£ò ${escapeHtml(p.motivo_perda)}</div>` : '';
    // Etiqueta r├ípida: nome do contato (ou data da ├║ltima intera├º├úo).
    const badgeTxt = p.contato ? p.contato : ('Intera├º├úo: ' + (p.last_interaction_date ? fmtDate(p.last_interaction_date) : 'ÔÇö'));
    const stg = stageClass(p);
    const tag = alertTag(p);
    return `
      <div class="kcard kcard-${p.status} ${stg}" draggable="true" data-id="${escapeHtml(p.id)}">
        <div class="kcard-top">
          <span class="kcard-id mono">${escapeHtml(p.id)}</span>
          <span class="kcard-badge">${escapeHtml(badgeTxt)}</span>
        </div>
        ${tag ? `<div class="kcard-alert-tag ${stg}">${escapeHtml(tag)}</div>` : ''}
        <div class="kcard-cliente">${escapeHtml(p.cliente)}</div>
        <div class="kcard-item">${escapeHtml(item)}</div>
        <div class="kcard-valor">${BRL(DB.totalProposta(p))}</div>
        ${motivo}
        <div class="kcard-actions">
          <button class="btn btn-ghost btn-sm" data-act="ver" data-id="${escapeHtml(p.id)}">Detalhes</button>
          <button class="btn btn-outline btn-sm" data-act="pdf" data-id="${escapeHtml(p.id)}">PDF</button>
        </div>
      </div>`;
  }

  function render() {
    const board = $('#kanban');
    const propostas = DB.getPropostas();
    board.innerHTML = '';

    const filtradas = filterTerm
      ? propostas.filter(p => {
          const term = filterTerm.toLowerCase();
          if (p.id.toLowerCase().includes(term)) return true;
          if ((p.cliente || '').toLowerCase().includes(term)) return true;
          return (p.itens || []).some(it => (it.nome || '').toLowerCase().includes(term));
        })
      : propostas;

    DB.STATUS_ORDER.forEach(key => {
      const st = DB.STATUS[key];
      const cards = filtradas.filter(p => p.status === key)
        // Novo no topo: ordena por data_movimentacao DESC.
        .sort((a, b) => new Date(b.data_movimentacao || 0) - new Date(a.data_movimentacao || 0));
      const total = cards.reduce((s, p) => s + DB.totalProposta(p), 0);

      const col = el('div', 'kanban-col');
      col.dataset.status = key;
      col.innerHTML = `
        <div class="kanban-col-header">
          <div class="kanban-col-head">
            <h3><span class="col-dot col-dot-${key}"></span>${COL_TITLES[key] || st.label}</h3>
            <span class="col-count">${cards.length}</span>
          </div>
          <div class="col-total">${BRL(total)}</div>
        </div>
        <div class="kanban-col-body">
          ${cards.map(cardHtml).join('') || '<p class="col-empty">Vazio</p>'}
        </div>`;
      board.appendChild(col);
    });

    bindDnD();
    bindActions();
  }

  function refreshDash() { const d = VIEWS.get('dashboard'); if (d) d.render(); }

  // N├║cleo: aplica a mudan├ºa de status; se for "perdido", exige motivo antes.
  function commitMove(id, novo, e) {
    const p = DB.getPropostas().find(x => x.id === id);
    if (!p || p.status === novo) return;

    // TRAVA FINANCEIRA: n├úo avan├ºar sem itens/valor da cota├º├úo.
    const idxAtual = DB.STATUS_ORDER.indexOf(p.status);
    const idxNovo = DB.STATUS_ORDER.indexOf(novo);
    if (idxNovo > idxAtual) {
      const total = DB.totalProposta(p);
      const semItens = !Array.isArray(p.itens) || p.itens.length === 0;
      if (semItens || total <= 0) {
        toast('Aten├º├úo: Adicione itens e valores antes de avan├ºar esta negocia├º├úo.');
        flashError(id);
        render(); // mant├®m o card na coluna original
        return;
      }
    }

    if (novo === 'perdido') {
      askMotivo(id, (motivo) => {
        DB.updateStatus(id, 'perdido', motivo);
        toast('Proposta marcada como perdida');
        render(); refreshDash();
      });
      return;
    }

    DB.updateStatus(id, novo);
    if (novo === 'ganho') {
      if (e) successBurst(e.clientX || window.innerWidth / 2, e.clientY || 200);
      toast('Proposta faturada! Faturamento atualizado.');
      render(); refreshDash();
      flashCard(id);
      // Gatilho de p├│s-venda: oferece o Resumo de Servi├ºo T├®cnico (OS).
      oferecerResumoOS(id);
      return;
    }
    render(); refreshDash();
    flashCard(id);
  }

  function bindActions() {
    $$('#kanban [data-act]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = btn.dataset.id;
        const act = btn.dataset.act;
        if (act === 'ver') showDetalhes(id);
        else if (act === 'pdf' && window.Proposta) { Proposta.gerarPdfById(id); }
      });
    });
  }

  function bindDnD() {
    $$('#kanban .kcard').forEach(card => {
      card.addEventListener('dragstart', () => { draggingId = card.dataset.id; card.classList.add('dragging'); });
      card.addEventListener('dragend', () => { draggingId = null; card.classList.remove('dragging'); $$('#kanban .kanban-col').forEach(c => c.classList.remove('drag-over')); });
    });
    $$('#kanban .kanban-col').forEach(col => {
      col.addEventListener('dragover', (e) => { e.preventDefault(); col.classList.add('drag-over'); });
      col.addEventListener('dragleave', () => col.classList.remove('drag-over'));
      col.addEventListener('drop', (e) => {
        e.preventDefault();
        col.classList.remove('drag-over');
        if (!draggingId) return;
        commitMove(draggingId, col.dataset.status, e);
      });
    });
  }

  // Modal obrigat├│rio de justificativa de perda/cancelamento.
  function askMotivo(id, onConfirm) {
    const p = DB.getPropostas().find(x => x.id === id);
    const box = el('div');
    box.innerHTML = `
      <p style="color:var(--text-2);font-size:13px;margin-bottom:14px">
        <strong>${escapeHtml(p ? p.cliente : '')}</strong> ÔÇö Qual o motivo da perda/cancelamento desta proposta?
        <br><span style="color:var(--text-3);font-size:12px">Este dado ├® obrigat├│rio e ser├í usado nos relat├│rios anal├¡ticos.</span>
      </p>
      <label class="field full" style="margin-bottom:12px">
        <span>Motivo r├ípido</span>
        <select id="mpSelect">
          <option value="">ÔÇö Selecione um motivo ÔÇö</option>
          ${MOTIVOS.map(m => `<option value="${escapeHtml(m)}">${escapeHtml(m)}</option>`).join('')}
          <option value="__outro">Outro (digitar)</option>
        </select>
      </label>
      <label class="field full" id="mpOutroWrap" style="display:none">
        <span>Descreva o motivo</span>
        <textarea id="mpOutro" placeholder="Digite a justificativa..." style="min-height:80px"></textarea>
      </label>
      <div class="modal-actions">
        <button class="btn btn-ghost" id="mpCancel">Cancelar</button>
        <button class="btn btn-danger" id="mpConfirm">Confirmar perda</button>
      </div>`;
    Modal.open('Motivo da Perda / Cancelamento', box);

    const sel = $('#mpSelect');
    sel.addEventListener('change', () => {
      const outro = sel.value === '__outro';
      $('#mpOutroWrap').style.display = outro ? '' : 'none';
      if (outro) setTimeout(() => $('#mpOutro').focus(), 30);
    });

    $('#mpCancel').addEventListener('click', () => { Modal.close(); render(); });
    $('#mpConfirm').addEventListener('click', () => {
      let motivo = sel.value;
      if (motivo === '__outro') motivo = $('#mpOutro').value.trim();
      if (!motivo) { toast('Selecione ou digite um motivo'); return; }
      Modal.close();
      onConfirm(motivo);
    });
  }

  // Tipos de atividade (sem emoji ÔÇö ├¡cone outline renderizado via CSS).
