    $('#mdDel').addEventListener('click', () => {
      if (confirm('Excluir esta proposta?')) { DB.deleteProposta(id); Modal.close(); render(); refreshDash(); toast('Proposta exclu├¡da'); }
    });
    $('#mdEdit').addEventListener('click', () => {
      // Entra em modo de edi├º├úo inline dos itens e cabe├ºalho.
      $('#dtItens').innerHTML = itensRows(true);
      // Substitui grid do cabe├ºalho por vers├úo edit├ível
