        <button class="btn btn-primary" id="mdSave">Salvar altera├º├Áes</button>`;
      // Recalcula linha/total ao digitar
      const recalc = () => {
        let total = 0;
        p.itens.forEach((it, i) => {
          const q = Number($(`.dt-qtd[data-i="${i}"]`).value) || 0;
          const pr = Number($(`.dt-preco[data-i="${i}"]`).value) || 0;
