        $$('.dt-rm', box).forEach(btn => btn.addEventListener('click', () => {
          const i = Number(btn.dataset.i);
          p.itens.splice(i, 1);
          $('#dtItens').innerHTML = itensRows(true);
          rebindEdit();
          recalc();
        }));
      };
      rebindEdit();
      recalc();
      // Adicionar item
      $('#mdAddItem').addEventListener('click', () => {
        p.itens.push({ nome: 'Novo item', descricao: '', qtd: 1, preco: 0, foto: '' });
