  // Gatilho de p├│s-venda: ao faturar, oferece gerar o Resumo de Servi├ºo T├®cnico.
  function oferecerResumoOS(id) {
    const p = DB.getPropostas().find(x => x.id === id);
    if (!p) return;
    const box = el('div');
    box.innerHTML = `
      <p style="color:var(--text-2);font-size:13px;margin-bottom:14px">
        Negocia├º├úo <strong>${escapeHtml(p.id)}</strong> faturada!<br>
        Deseja gerar o <strong>Resumo de Servi├ºo T├®cnico</strong> para abrir a Ordem de Servi├ºo (OS) com os t├®cnicos de campo?
      </p>
      <div class="modal-actions">
        <button class="btn btn-ghost" id="osSkip">Agora n├úo</button>
        <button class="btn btn-success" id="osGerar">Gerar Resumo de Servi├ºo</button>
      </div>`;
    Modal.open('P├│s-Venda ÔÇö Ordem de Servi├ºo', box);
    $('#osSkip').addEventListener('click', Modal.close);
    $('#osGerar').addEventListener('click', () => { Modal.close(); gerarResumoOS(p); });
  }

  // Compila um briefing limpo (texto) para a Ordem de Servi├ºo.
  function gerarResumoOS(p) {
