    corp: [
      'METROLABÔÇÖS SOLU├ç├òES EM ENGENHARIA CL├ìNICA',
      'CNPJ: 32.487.278/0001-21',
      'Rua C 155, N┬║ 789, Qd 365, Lt 08 ÔÇö Jardim Am├®rica, Goi├ónia - GO',
