  /* ---------- MOTOR DE PDF EXECUTIVO ÔÇö MODELO METROLABS (A4) ---------- */
  /* Gera DOIS arquivos independentes: Proposta T├®cnica e Proposta Comercial.
     Cada PDF usa fluxo natural (autoTable com border-collapse e linebreak),
     sem alturas fixas r├¡gidas, evitando sobreposi├º├úo de texto. */

  function gerarPdf(prop, modo, comDescricao) {
    if (!window.jspdf) { toast('Biblioteca de PDF n├úo carregou. Recarregue a p├ígina.'); return; }
    if (!prop || !prop.itens || !prop.itens.length) { toast('Adicione ao menos um item para gerar o PDF'); return; }
    const m = modo || 'ambas';
    try {
      if (m === 'tecnica' || m === 'ambas') gerarTecnica(prop);
      if (m === 'comercial' || m === 'ambas') {
        if (typeof (new window.jspdf.jsPDF()).autoTable !== 'function') {
          toast('Plugin de tabela (autoTable) n├úo carregou. Recarregue a p├ígina.'); return;
        }
        gerarComercial(prop, comDescricao);
      }
      const lbl = m === 'tecnica' ? 'Proposta T├®cnica' : m === 'comercial' ? 'Proposta Comercial' : 'Propostas T├®cnica e Comercial';
      toast(lbl + ' gerada(s)');
    } catch (e) {
      console.error('Erro ao gerar PDF:', e);
      toast('Erro ao gerar PDF: ' + (e && e.message ? e.message : e));
    }
  }

  // Modal de sele├º├úo flex├¡vel do tipo de documento a emitir.
  // Recebe a proposta e uma flag se deve registrar no hist├│rico de emiss├Áes.
